BEGIN;

INSERT INTO public.solas (id, slug, order_index, latin, name_en, name_es, name_pt, translation_en, translation_es, translation_pt, explanation_en, explanation_es, explanation_pt, history_en, history_es, history_pt, verses_en, verses_es, verses_pt, application_en, application_es, application_pt, created_at, updated_at)
SELECT id, slug, order_index, latin, name_en, name_es, name_pt, translation_en, translation_es, translation_pt, explanation_en, explanation_es, explanation_pt, history_en, history_es, history_pt, verses_en, verses_es, verses_pt, application_en, application_es, application_pt, created_at, updated_at
FROM jsonb_populate_recordset(NULL::public.solas, $pf_library$[
{"id":"48bd622a-d395-4d7e-88d2-09006bd98159","slug":"sola-scriptura","order_index":1,"latin":"Sola Scriptura","name_en":"Sola Scriptura","name_es":"Sola Scriptura","name_pt":"Sola Scriptura","translation_en":"Scripture Alone","translation_es":"Solo la Escritura","translation_pt":"Somente a Escritura","explanation_en":"According to the Protestant doctrine of Sola Scriptura, Scripture is the supreme authority in matters of faith and practice.","explanation_es":"Según la doctrina protestante de Sola Scriptura, la Escritura es la suprema autoridad en asuntos de fe y práctica.","explanation_pt":"Segundo a doutrina protestante de Sola Scriptura, a Escritura é a suprema autoridade em matéria de fé e prática.","history_en":"The expression \"Sola Scriptura\" is not found verbatim in Scripture; it is a theological summary of the Reformers' teaching that the Bible alone is the supreme authority for faith and practice, developed during the Protestant Reformation of the 16th century. At the Diet of Worms (1521), Martin Luther declared his conscience captive to the Word of God.","history_es":"La expresión \"Sola Scriptura\" no se encuentra textualmente en la Escritura; es un resumen teológico de la enseñanza de los Reformadores sobre que la Biblia sola es la suprema autoridad en fe y práctica, desarrollado durante la Reforma Protestante del siglo XVI. En la Dieta de Worms (1521), Martín Lutero declaró su conciencia cautiva a la Palabra de Dios.","history_pt":"A expressão \"Sola Scriptura\" não se encontra textualmente nas Escrituras; é um resumo teológico do ensino dos Reformadores de que somente a Bíblia é a suprema autoridade em fé e prática, desenvolvido durante a Reforma Protestante do século XVI. Na Dieta de Worms (1521), Martinho Lutero declarou sua consciência cativa à Palavra de Deus.","verses_en":"2 Timothy 3:16–17; Isaiah 8:20; Matthew 4:4; Acts 17:11; Revelation 22:18–19","verses_es":"2 Timoteo 3:16–17; Isaías 8:20; Mateo 4:4; Hechos 17:11; Apocalipsis 22:18–19","verses_pt":"2 Timóteo 3:16–17; Isaías 8:20; Mateus 4:4; Atos 17:11; Apocalipse 22:18–19","application_en":"Read Scripture daily. Weigh every teaching — sermon, book, or trend — against the Bible. Let God's Word shape your convictions rather than culture or personal preference.","application_es":"Lee la Escritura diariamente. Pesa toda enseñanza — sermón, libro o tendencia — contra la Biblia. Deja que la Palabra de Dios forme tus convicciones y no la cultura o preferencia personal.","application_pt":"Leia as Escrituras diariamente. Pese todo ensino — sermão, livro ou tendência — pela Bíblia. Deixe a Palavra de Deus formar suas convicções, e não a cultura ou preferência pessoal.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-08-02T00:57:27.671177+00:00"},
{"id":"b8a342e2-894f-42e9-a273-957767bc7d04","slug":"sola-fide","order_index":2,"latin":"Sola Fide","name_en":"Sola Fide","name_es":"Sola Fide","name_pt":"Sola Fide","translation_en":"Faith Alone","translation_es":"Solo la Fe","translation_pt":"Somente a Fé","explanation_en":"Sola Fide is a Protestant summary of the biblical teaching that we are justified — declared righteous before God — by faith alone in Jesus Christ, apart from any works of the law. Faith is the empty hand that receives the finished work of Christ.","explanation_es":"Sola Fide es un resumen protestante de la enseñanza bíblica de que somos justificados — declarados justos delante de Dios — por la fe sola en Jesucristo, aparte de cualquier obra de la ley. La fe es la mano vacía que recibe la obra terminada de Cristo.","explanation_pt":"Sola Fide é um resumo protestante do ensino bíblico de que somos justificados — declarados justos diante de Deus — pela fé somente em Jesus Cristo, à parte de qualquer obra da lei. A fé é a mão vazia que recebe a obra consumada de Cristo.","history_en":"The phrase \"Sola Fide\" does not appear verbatim in the Bible; it is a theological summary the Reformers used to recover the apostolic teaching of justification by faith. Luther rediscovered this truth studying Romans 1:17. The medieval church had taught justification through faith combined with sacraments and merit; the Reformers restored Paul's gospel: righteousness is a gift, received, never earned.","history_es":"La frase \"Sola Fide\" no aparece textualmente en la Biblia; es un resumen teológico que los Reformadores usaron para restaurar la enseñanza apostólica de la justificación por la fe. Lutero redescubrió esta verdad estudiando Romanos 1:17. La iglesia medieval enseñaba la justificación por la fe combinada con sacramentos y méritos; los Reformadores restauraron el evangelio de Pablo: la justicia es un don recibido, nunca ganado.","history_pt":"A frase \"Sola Fide\" não aparece textualmente na Bíblia; é um resumo teológico que os Reformadores usaram para restaurar o ensino apostólico da justificação pela fé. Lutero redescobriu esta verdade estudando Romanos 1:17. A igreja medieval ensinava justificação pela fé combinada com sacramentos e méritos; os Reformadores restauraram o evangelho de Paulo: a justiça é um dom recebido, nunca conquistado.","verses_en":"Romans 3:28; Romans 4:5; Galatians 2:16; Ephesians 2:8–9; Philippians 3:9","verses_es":"Romanos 3:28; Romanos 4:5; Gálatas 2:16; Efesios 2:8–9; Filipenses 3:9","verses_pt":"Romanos 3:28; Romanos 4:5; Gálatas 2:16; Efésios 2:8–9; Filipenses 3:9","application_en":"Stop trying to earn what Christ has already secured. Rest in His righteousness. Good works flow from faith, not toward it.","application_es":"Deja de intentar ganar lo que Cristo ya aseguró. Descansa en Su justicia. Las buenas obras fluyen de la fe, no hacia ella.","application_pt":"Pare de tentar merecer o que Cristo já garantiu. Descanse em Sua justiça. As boas obras fluem da fé, não em direção a ela.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-08-02T00:57:27.671177+00:00"},
{"id":"94b9526f-5588-4068-a6cd-2ccab2bb59b4","slug":"sola-gratia","order_index":3,"latin":"Sola Gratia","name_en":"Sola Gratia","name_es":"Sola Gratia","name_pt":"Sola Gratia","translation_en":"Grace Alone","translation_es":"Solo la Gracia","translation_pt":"Somente a Graça","explanation_en":"Sola Gratia is a Protestant summary of the biblical teaching that salvation is entirely a gift of God's unmerited favor. From election to calling to justification to glorification, every step is grace. We contribute nothing to our salvation but the sin from which we are saved.","explanation_es":"Sola Gratia es un resumen protestante de la enseñanza bíblica de que la salvación es enteramente un don del favor inmerecido de Dios. Desde la elección hasta la vocación, la justificación y la glorificación, cada paso es gracia. No aportamos nada a nuestra salvación excepto el pecado del cual somos salvados.","explanation_pt":"Sola Gratia é um resumo protestante do ensino bíblico de que a salvação é inteiramente um dom do favor imerecido de Deus. Da eleição ao chamado, à justificação e à glorificação, cada passo é graça. Nada contribuímos para nossa salvação senão o pecado do qual somos salvos.","history_en":"The expression \"Sola Gratia\" is not a literal biblical phrase; it is a theological summary the Reformers used to defend grace against any teaching that made it dependent on human cooperation. Augustine had opposed Pelagius in the 5th century, and a thousand years later the Reformers, especially Calvin, systematized this truth in the 16th-century Reformation.","history_es":"La expresión \"Sola Gratia\" no es una frase literal bíblica; es un resumen teológico que los Reformadores usaron para defender la gracia contra toda enseñanza que la hiciera dependiente de la cooperación humana. Agustín se opuso a Pelagio en el siglo V, y mil años después los Reformadores, especialmente Calvino, sistematizaron esta verdad en la Reforma del siglo XVI.","history_pt":"A expressão \"Sola Gratia\" não é uma frase literal bíblica; é um resumo teológico que os Reformadores usaram para defender a graça contra todo ensino que a tornasse dependente da cooperação humana. Agostinho opôs-se a Pelágio no século V, e mil anos depois os Reformadores, especialmente Calvino, sistematizaram esta verdade na Reforma do século XVI.","verses_en":"Ephesians 2:4–9; Romans 11:6; Titus 3:5–7; 2 Timothy 1:9; Romans 9:16","verses_es":"Efesios 2:4–9; Romanos 11:6; Tito 3:5–7; 2 Timoteo 1:9; Romanos 9:16","verses_pt":"Efésios 2:4–9; Romanos 11:6; Tito 3:5–7; 2 Timóteo 1:9; Romanos 9:16","application_en":"Cultivate humility and gratitude. Never boast in your walk with God — every good thing is grace. Extend that same grace to others.","application_es":"Cultiva humildad y gratitud. Nunca te jactes de tu caminar con Dios — todo lo bueno es gracia. Extiende esa misma gracia a otros.","application_pt":"Cultive humildade e gratidão. Nunca se vanglorie de sua caminhada com Deus — todo bem é graça. Estenda essa mesma graça aos outros.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-08-02T00:57:27.671177+00:00"},
{"id":"58e7f438-402f-4d70-9e5d-bcfdc5478bfb","slug":"solus-christus","order_index":4,"latin":"Solus Christus","name_en":"Solus Christus","name_es":"Solus Christus","name_pt":"Solus Christus","translation_en":"Christ Alone","translation_es":"Solo Cristo","translation_pt":"Somente Cristo","explanation_en":"Solus Christus is a Protestant summary of the biblical teaching that Jesus Christ is the sole mediator between God and humanity. His life, death, and resurrection are the only ground of our salvation. No saint, priest, ritual, or sacrament can add to His finished work.","explanation_es":"Solus Christus es un resumen protestante de la enseñanza bíblica de que Jesucristo es el único mediador entre Dios y el hombre. Su vida, muerte y resurrección son el único fundamento de nuestra salvación. Ningún santo, sacerdote, rito o sacramento puede añadir a Su obra consumada.","explanation_pt":"Solus Christus é um resumo protestante do ensino bíblico de que Jesus Cristo é o único mediador entre Deus e o homem. Sua vida, morte e ressurreição são o único fundamento de nossa salvação. Nenhum santo, sacerdote, rito ou sacramento pode acrescentar à Sua obra consumada.","history_en":"The words \"Solus Christus\" do not appear verbatim in the Bible; they are a theological summary the Reformers used to reject the medieval system of intermediaries and to return to the New Testament's exclusive focus on Christ as prophet, priest, and king.","history_es":"Las palabras \"Solus Christus\" no aparecen textualmente en la Biblia; son un resumen teológico que los Reformadores usaron para rechazar el sistema medieval de intermediarios y regresar al enfoque exclusivo del Nuevo Testamento en Cristo como profeta, sacerdote y rey.","history_pt":"As palavras \"Solus Christus\" não aparecem textualmente na Bíblia; são um resumo teológico que os Reformadores usaram para rejeitar o sistema medieval de intermediários e retornar ao foco exclusivo do Novo Testamento em Cristo como profeta, sacerdote e rei.","verses_en":"John 14:6; 1 Timothy 2:5; Acts 4:12; Hebrews 7:25; Hebrews 10:12","verses_es":"Juan 14:6; 1 Timoteo 2:5; Hechos 4:12; Hebreos 7:25; Hebreos 10:12","verses_pt":"João 14:6; 1 Timóteo 2:5; Atos 4:12; Hebreus 7:25; Hebreus 10:12","application_en":"Pray directly to the Father through Christ. Trust His sufficiency — you need no other advocate. Point others to Him alone.","application_es":"Ora directamente al Padre por medio de Cristo. Confía en Su suficiencia — no necesitas otro abogado. Señala a otros a Él solo.","application_pt":"Ore diretamente ao Pai por meio de Cristo. Confie em Sua suficiência — não precisa de outro advogado. Aponte outros somente para Ele.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-08-02T00:57:27.671177+00:00"},
{"id":"412fd863-ae3e-4e39-9228-eb9d7860f6ea","slug":"soli-deo-gloria","order_index":5,"latin":"Soli Deo Gloria","name_en":"Soli Deo Gloria","name_es":"Soli Deo Gloria","name_pt":"Soli Deo Gloria","translation_en":"Glory to God Alone","translation_es":"Gloria solo a Dios","translation_pt":"Glória somente a Deus","explanation_en":"Soli Deo Gloria is a Protestant summary of the biblical teaching that all of life exists for the glory of God. Salvation, worship, work, and rest — everything ultimately serves to magnify Him. No credit for our redemption or our lives belongs to us.","explanation_es":"Soli Deo Gloria es un resumen protestante de la enseñanza bíblica de que toda la vida existe para la gloria de Dios. Salvación, adoración, trabajo y descanso — todo sirve finalmente para magnificarle. Ningún mérito por nuestra redención o nuestras vidas nos pertenece.","explanation_pt":"Soli Deo Gloria é um resumo protestante do ensino bíblico de que toda a vida existe para a glória de Deus. Salvação, adoração, trabalho e descanso — tudo serve finalmente para magnificá-Lo. Nenhum mérito por nossa redenção ou nossas vidas nos pertence.","history_en":"The phrase \"Soli Deo Gloria\" is not found word-for-word in Scripture; it is a theological summary that became the capstone of the Protestant Reformation. If Scripture, faith, grace, and Christ alone save us, then God alone gets the glory. J.S. Bach famously signed his manuscripts \"S.D.G.\" to dedicate his art to God.","history_es":"La frase \"Soli Deo Gloria\" no se encuentra textualmente en la Escritura; es un resumen teológico que se convirtió en el cierre de la Reforma Protestante. Si la Escritura, la fe, la gracia y Cristo solo nos salvan, entonces solo Dios recibe la gloria. J.S. Bach firmaba sus manuscritos \"S.D.G.\" para dedicar su arte a Dios.","history_pt":"A frase \"Soli Deo Gloria\" não se encontra textualmente nas Escrituras; é um resumo teológico que se tornou o arremate da Reforma Protestante. Se Escritura, fé, graça e Cristo somente nos salvam, então somente Deus recebe a glória. J.S. Bach assinava seus manuscritos \"S.D.G.\" para dedicar sua arte a Deus.","verses_en":"1 Corinthians 10:31; Romans 11:36; Psalm 115:1; Isaiah 42:8; Revelation 4:11","verses_es":"1 Corintios 10:31; Romanos 11:36; Salmo 115:1; Isaías 42:8; Apocalipsis 4:11","verses_pt":"1 Coríntios 10:31; Romanos 11:36; Salmo 115:1; Isaías 42:8; Apocalipse 4:11","application_en":"Do everything — eating, working, resting — to God's glory. Refuse to steal credit that belongs to Him. Let your life point beyond yourself.","application_es":"Haz todo — comer, trabajar, descansar — para la gloria de Dios. Rehúsa robar el crédito que le pertenece. Que tu vida apunte más allá de ti mismo.","application_pt":"Faça tudo — comer, trabalhar, descansar — para a glória de Deus. Recuse-se a roubar o crédito que Lhe pertence. Que sua vida aponte além de você mesmo.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-08-02T00:57:27.671177+00:00"}
]$pf_library$::jsonb)
ON CONFLICT DO NOTHING;

INSERT INTO public.greek_words (id, slug, order_index, greek, transliteration, pronunciation, meaning_en, meaning_es, meaning_pt, biblical_usage_en, biblical_usage_es, biblical_usage_pt, scripture_refs, explanation_en, explanation_es, explanation_pt, created_at, updated_at, language_type, ipa, literal_meaning_en, literal_meaning_es, literal_meaning_pt, biblical_meaning_en, biblical_meaning_es, biblical_meaning_pt, historical_background_en, historical_background_es, historical_background_pt, practical_application_en, practical_application_es, practical_application_pt, related_words, pronunciation_text, pronunciation_locale)
SELECT id, slug, order_index, greek, transliteration, pronunciation, meaning_en, meaning_es, meaning_pt, biblical_usage_en, biblical_usage_es, biblical_usage_pt, scripture_refs, explanation_en, explanation_es, explanation_pt, created_at, updated_at, language_type, ipa, literal_meaning_en, literal_meaning_es, literal_meaning_pt, biblical_meaning_en, biblical_meaning_es, biblical_meaning_pt, historical_background_en, historical_background_es, historical_background_pt, practical_application_en, practical_application_es, practical_application_pt, related_words, pronunciation_text, pronunciation_locale
FROM jsonb_populate_recordset(NULL::public.greek_words, $pf_library$[
{"id":"f0dc910c-6d23-4e69-aa37-7cc2da304ac2","slug":"agape","order_index":1,"greek":"ἀγάπη","transliteration":"agapē","pronunciation":"ah-GAH-pay","meaning_en":"Selfless, sacrificial, unconditional love","meaning_es":"Amor abnegado, sacrificial e incondicional","meaning_pt":"Amor abnegado, sacrificial e incondicional","biblical_usage_en":"The love God has for humanity, and the love believers are called to show one another.","biblical_usage_es":"El amor que Dios tiene por la humanidad, y el amor que los creyentes deben mostrarse unos a otros.","biblical_usage_pt":"O amor que Deus tem pela humanidade, e o amor que os crentes devem mostrar uns aos outros.","scripture_refs":"John 3:16; 1 Corinthians 13; 1 John 4:8","explanation_en":"Agape describes the highest form of love — love that gives without expecting return. It is the defining mark of Christian discipleship.","explanation_es":"Agape describe la forma más alta de amor — un amor que da sin esperar retorno. Es la marca distintiva del discipulado cristiano.","explanation_pt":"Agape descreve a forma mais alta de amor — amor que dá sem esperar retorno. É a marca distintiva do discipulado cristão.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"f18c8e49-8017-455c-92e1-a8810a4c6cbd","slug":"logos","order_index":2,"greek":"λόγος","transliteration":"logos","pronunciation":"LOH-gos","meaning_en":"Word, message, reason","meaning_es":"Palabra, mensaje, razón","meaning_pt":"Palavra, mensagem, razão","biblical_usage_en":"Used of Jesus as the eternal Word of God who reveals the Father.","biblical_usage_es":"Usado de Jesús como la Palabra eterna de Dios que revela al Padre.","biblical_usage_pt":"Usado de Jesus como a Palavra eterna de Deus que revela o Pai.","scripture_refs":"John 1:1–14; Hebrews 4:12; Revelation 19:13","explanation_en":"John opens his Gospel by identifying Christ as the Logos — God's self-expression made flesh.","explanation_es":"Juan abre su Evangelio identificando a Cristo como el Logos — la autoexpresión de Dios hecha carne.","explanation_pt":"João abre seu Evangelho identificando Cristo como o Logos — a autoexpressão de Deus feita carne.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"f4191f11-caac-4987-9129-306143bd1e7a","slug":"christos","order_index":3,"greek":"Χριστός","transliteration":"Christos","pronunciation":"khrist-OS","meaning_en":"Anointed One, Messiah","meaning_es":"Ungido, Mesías","meaning_pt":"Ungido, Messias","biblical_usage_en":"The title given to Jesus as the promised King and Deliverer.","biblical_usage_es":"El título dado a Jesús como el Rey y Libertador prometido.","biblical_usage_pt":"O título dado a Jesus como o Rei e Libertador prometido.","scripture_refs":"Matthew 16:16; John 20:31; Acts 2:36","explanation_en":"Christos is the Greek equivalent of the Hebrew Mashiach. To confess Jesus as Christ is to confess Him as the promised King.","explanation_es":"Christos es el equivalente griego del hebreo Mashiach. Confesar a Jesús como Cristo es confesarle como el Rey prometido.","explanation_pt":"Christos é o equivalente grego do hebraico Mashiach. Confessar Jesus como Cristo é confessá-Lo como o Rei prometido.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"dbd40622-acfc-453e-8d7e-be74bf7d508e","slug":"pistis","order_index":4,"greek":"πίστις","transliteration":"pistis","pronunciation":"PIS-tis","meaning_en":"Faith, trust, faithfulness","meaning_es":"Fe, confianza, fidelidad","meaning_pt":"Fé, confiança, fidelidade","biblical_usage_en":"The trust that receives God's promises and clings to Christ for salvation.","biblical_usage_es":"La confianza que recibe las promesas de Dios y se aferra a Cristo para la salvación.","biblical_usage_pt":"A confiança que recebe as promessas de Deus e se apega a Cristo para a salvação.","scripture_refs":"Hebrews 11:1; Romans 10:17; Ephesians 2:8","explanation_en":"Pistis is more than intellectual assent — it is heart-level trust that transforms how we live.","explanation_es":"Pistis es más que asentimiento intelectual — es confianza del corazón que transforma cómo vivimos.","explanation_pt":"Pistis é mais que assentimento intelectual — é confiança do coração que transforma como vivemos.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"99b755e6-88c5-46e4-9f7c-38179686645d","slug":"charis","order_index":5,"greek":"χάρις","transliteration":"charis","pronunciation":"KHAR-is","meaning_en":"Grace, unmerited favor","meaning_es":"Gracia, favor inmerecido","meaning_pt":"Graça, favor imerecido","biblical_usage_en":"God's free gift of salvation and daily kindness toward His people.","biblical_usage_es":"El don gratuito de salvación de Dios y bondad diaria hacia Su pueblo.","biblical_usage_pt":"O dom gratuito de salvação de Deus e bondade diária para com Seu povo.","scripture_refs":"Ephesians 2:8; 2 Corinthians 12:9; Titus 2:11","explanation_en":"Charis is the very atmosphere of the gospel — everything received from God is unearned.","explanation_es":"Charis es la atmósfera misma del evangelio — todo lo recibido de Dios es inmerecido.","explanation_pt":"Charis é a atmosfera do evangelho — tudo o que recebemos de Deus é imerecido.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"bed48eee-909e-4957-b225-98442979549a","slug":"kurios","order_index":6,"greek":"κύριος","transliteration":"kurios","pronunciation":"KOO-ree-os","meaning_en":"Lord, master","meaning_es":"Señor, amo","meaning_pt":"Senhor, mestre","biblical_usage_en":"A divine title applied to Jesus, affirming His deity and rightful rule.","biblical_usage_es":"Un título divino aplicado a Jesús, afirmando Su deidad y gobierno legítimo.","biblical_usage_pt":"Um título divino aplicado a Jesus, afirmando Sua deidade e domínio legítimo.","scripture_refs":"Romans 10:9; Philippians 2:11; Acts 2:36","explanation_en":"To call Jesus Kurios is to submit every part of life to His authority.","explanation_es":"Llamar a Jesús Kurios es someter cada parte de la vida a Su autoridad.","explanation_pt":"Chamar Jesus de Kurios é submeter cada parte da vida à Sua autoridade.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"2402be83-69c6-40dc-b8a8-0fc1b6ba4633","slug":"ekklesia","order_index":7,"greek":"ἐκκλησία","transliteration":"ekklēsia","pronunciation":"ek-klay-SEE-ah","meaning_en":"Church, called-out assembly","meaning_es":"Iglesia, asamblea llamada","meaning_pt":"Igreja, assembleia chamada","biblical_usage_en":"The gathered people of God, both local congregations and the universal church.","biblical_usage_es":"El pueblo reunido de Dios, tanto congregaciones locales como la iglesia universal.","biblical_usage_pt":"O povo reunido de Deus, tanto congregações locais como a igreja universal.","scripture_refs":"Matthew 16:18; Acts 2:47; Ephesians 5:25","explanation_en":"The church is not a building but a people called out of the world by Christ for worship and mission.","explanation_es":"La iglesia no es un edificio sino un pueblo llamado del mundo por Cristo para adoración y misión.","explanation_pt":"A igreja não é um edifício mas um povo chamado do mundo por Cristo para adoração e missão.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"0d37e0fc-26ea-4db0-adc3-dae7d4303a13","slug":"baptizo","order_index":8,"greek":"βαπτίζω","transliteration":"baptizō","pronunciation":"bap-TID-zoh","meaning_en":"To immerse, to baptize","meaning_es":"Sumergir, bautizar","meaning_pt":"Imergir, batizar","biblical_usage_en":"The act of baptism as public identification with the death, burial, and resurrection of Christ.","biblical_usage_es":"El acto del bautismo como identificación pública con la muerte, sepultura y resurrección de Cristo.","biblical_usage_pt":"O ato do batismo como identificação pública com a morte, sepultamento e ressurreição de Cristo.","scripture_refs":"Matthew 28:19; Romans 6:3–4; Acts 2:38","explanation_en":"Baptism visibly signs the believer's union with Christ and entrance into the covenant community.","explanation_es":"El bautismo señala visiblemente la unión del creyente con Cristo y la entrada a la comunidad del pacto.","explanation_pt":"O batismo assinala visivelmente a união do crente com Cristo e a entrada na comunidade da aliança.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"8901880c-59b7-493f-8f23-f5d5148b6fcd","slug":"metanoia","order_index":9,"greek":"μετάνοια","transliteration":"metanoia","pronunciation":"met-AH-noy-ah","meaning_en":"Repentance, change of mind","meaning_es":"Arrepentimiento, cambio de mente","meaning_pt":"Arrependimento, mudança de mente","biblical_usage_en":"A God-given turning from sin to Christ that reshapes both thinking and life.","biblical_usage_es":"Un giro dado por Dios del pecado a Cristo que reforma tanto el pensamiento como la vida.","biblical_usage_pt":"Uma mudança dada por Deus do pecado a Cristo que reforma tanto o pensar como a vida.","scripture_refs":"Matthew 3:2; Acts 3:19; 2 Corinthians 7:10","explanation_en":"Metanoia is not mere regret. It is a Spirit-worked reorientation of the whole person toward God.","explanation_es":"Metanoia no es mero remordimiento. Es una reorientación obrada por el Espíritu de toda la persona hacia Dios.","explanation_pt":"Metanoia não é mero remorso. É uma reorientação operada pelo Espírito de toda a pessoa em direção a Deus.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"1f3a8120-c563-4da0-b719-266e287aee81","slug":"pneuma","order_index":10,"greek":"πνεῦμα","transliteration":"pneuma","pronunciation":"p-NYOO-mah","meaning_en":"Spirit, breath, wind","meaning_es":"Espíritu, aliento, viento","meaning_pt":"Espírito, sopro, vento","biblical_usage_en":"Used of the Holy Spirit, of the human spirit, and of the breath of life.","biblical_usage_es":"Usado del Espíritu Santo, del espíritu humano, y del aliento de vida.","biblical_usage_pt":"Usado do Espírito Santo, do espírito humano, e do sopro de vida.","scripture_refs":"John 3:8; Acts 2:4; Romans 8:9","explanation_en":"Pneuma reminds us that God's Spirit is as invisible and as vital as the breath in our lungs.","explanation_es":"Pneuma nos recuerda que el Espíritu de Dios es tan invisible y tan vital como el aliento en nuestros pulmones.","explanation_pt":"Pneuma nos lembra que o Espírito de Deus é tão invisível e tão vital como o sopro em nossos pulmões.","created_at":"2026-07-02T16:29:26.050016+00:00","updated_at":"2026-07-02T16:29:26.050016+00:00","language_type":"greek","ipa":null,"literal_meaning_en":null,"literal_meaning_es":null,"literal_meaning_pt":null,"biblical_meaning_en":null,"biblical_meaning_es":null,"biblical_meaning_pt":null,"historical_background_en":null,"historical_background_es":null,"historical_background_pt":null,"practical_application_en":null,"practical_application_es":null,"practical_application_pt":null,"related_words":null,"pronunciation_text":null,"pronunciation_locale":null},
{"id":"98c6d171-e482-46f4-9616-e6a25458bf04","slug":"phileo","order_index":11,"greek":"φιλέω","transliteration":"phileō","pronunciation":"fee-LEH-oh","meaning_en":"Affectionate, brotherly love; friendship love.","meaning_es":"Amor afectuoso y fraternal; amor de amistad.","meaning_pt":"Amor afetuoso e fraternal; amor de amizade.","biblical_usage_en":"Used when Jesus asks Peter, 'Do you love me?' contrasting phileō and agapē.","biblical_usage_es":"Usado cuando Jesús pregunta a Pedro '¿Me amas?', contrastando phileō y ágape.","biblical_usage_pt":"Usado quando Jesus pergunta a Pedro 'Você me ama?', contrastando phileō e ágape.","scripture_refs":"John 21:15-17; Romans 12:10","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"fiˈleo","literal_meaning_en":"To love as a friend, to have deep fondness.","literal_meaning_es":"Amar como amigo, tener profundo cariño.","literal_meaning_pt":"Amar como amigo, ter profunda afeição.","biblical_meaning_en":"The warm bond of friendship God places among His people.","biblical_meaning_es":"El vínculo cálido de amistad que Dios coloca entre su pueblo.","biblical_meaning_pt":"O vínculo caloroso de amizade que Deus coloca entre seu povo.","historical_background_en":"One of four Greek words for love; distinct from agapē (self-giving) and erōs (romantic).","historical_background_es":"Una de las cuatro palabras griegas para amor; distinta de ágape y eros.","historical_background_pt":"Uma das quatro palavras gregas para amor; distinta de ágape e eros.","practical_application_en":"Cultivate warm friendship within the church, not only duty.","practical_application_es":"Cultiva amistad cálida en la iglesia, no solo deber.","practical_application_pt":"Cultive amizade calorosa na igreja, não apenas dever.","related_words":"agapē; storgē; erōs","pronunciation_text":null,"pronunciation_locale":null},
{"id":"4cab3445-a2bd-4ec2-8a26-44cde55d71c8","slug":"sozo","order_index":12,"greek":"σῴζω","transliteration":"sōzō","pronunciation":"SOD-zoh","meaning_en":"To save, deliver, heal, preserve.","meaning_es":"Salvar, librar, sanar, preservar.","meaning_pt":"Salvar, livrar, curar, preservar.","biblical_usage_en":"Used of physical healing and eternal salvation in the Gospels.","biblical_usage_es":"Usado para sanación física y salvación eterna en los Evangelios.","biblical_usage_pt":"Usado para cura física e salvação eterna nos Evangelhos.","scripture_refs":"Matthew 1:21; Acts 4:12; Romans 10:9","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"ˈsɔːzɔː","literal_meaning_en":"To rescue from danger, harm, or destruction.","literal_meaning_es":"Rescatar del peligro, daño o destrucción.","literal_meaning_pt":"Resgatar do perigo, dano ou destruição.","biblical_meaning_en":"Salvation from sin, death, and judgment through Christ.","biblical_meaning_es":"Salvación del pecado, la muerte y el juicio por medio de Cristo.","biblical_meaning_pt":"Salvação do pecado, da morte e do juízo por meio de Cristo.","historical_background_en":"Common in Greek medical, military, and religious contexts.","historical_background_es":"Común en contextos griegos médicos, militares y religiosos.","historical_background_pt":"Comum em contextos gregos médicos, militares e religiosos.","practical_application_en":"Trust Christ for salvation; share this good news with others.","practical_application_es":"Confía en Cristo para salvación; comparte esta buena nueva.","practical_application_pt":"Confie em Cristo para a salvação; compartilhe esta boa nova.","related_words":"sōtēria; sōtēr","pronunciation_text":null,"pronunciation_locale":null},
{"id":"20e350dd-c13e-4236-ad75-7dd591b06724","slug":"doxa","order_index":13,"greek":"δόξα","transliteration":"doxa","pronunciation":"DOX-ah","meaning_en":"Glory, honor, splendor, radiance.","meaning_es":"Gloria, honor, esplendor, resplandor.","meaning_pt":"Glória, honra, esplendor, resplendor.","biblical_usage_en":"Used of the shekhinah glory, Christ's transfiguration, and heaven.","biblical_usage_es":"Usado para la gloria shekiná, la transfiguración de Cristo y el cielo.","biblical_usage_pt":"Usado para a glória shekiná, a transfiguração de Cristo e o céu.","scripture_refs":"John 1:14; Romans 3:23; 2 Corinthians 3:18","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"ˈdoksa","literal_meaning_en":"Weightiness of reputation; brilliant manifestation.","literal_meaning_es":"Peso de reputación; manifestación brillante.","literal_meaning_pt":"Peso de reputação; manifestação brilhante.","biblical_meaning_en":"The visible manifestation of God's presence and worth.","biblical_meaning_es":"La manifestación visible de la presencia y el valor de Dios.","biblical_meaning_pt":"A manifestação visível da presença e do valor de Deus.","historical_background_en":"Translates Hebrew 'kavod' in the Septuagint.","historical_background_es":"Traduce el hebreo 'kavod' en la Septuaginta.","historical_background_pt":"Traduz o hebraico 'kavod' na Septuaginta.","practical_application_en":"Live for God's glory in every ordinary moment.","practical_application_es":"Vive para la gloria de Dios en cada momento ordinario.","practical_application_pt":"Viva para a glória de Deus em cada momento ordinário.","related_words":"doxazō; kavod","pronunciation_text":null,"pronunciation_locale":null},
{"id":"3f496699-394d-41a8-ba56-97ef5685233b","slug":"hagios","order_index":14,"greek":"ἅγιος","transliteration":"hagios","pronunciation":"HA-gee-os","meaning_en":"Holy, set apart, sacred.","meaning_es":"Santo, apartado, sagrado.","meaning_pt":"Santo, separado, sagrado.","biblical_usage_en":"Believers are called 'hagioi' — saints, set apart in Christ.","biblical_usage_es":"Los creyentes son llamados 'hagioi' — santos, apartados en Cristo.","biblical_usage_pt":"Os crentes são chamados 'hagioi' — santos, separados em Cristo.","scripture_refs":"1 Peter 1:16; Romans 1:7","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"ˈhaɡios","literal_meaning_en":"Separated from common use for God.","literal_meaning_es":"Separado del uso común para Dios.","literal_meaning_pt":"Separado do uso comum para Deus.","biblical_meaning_en":"God's moral perfection and consecration of His people.","biblical_meaning_es":"La perfección moral de Dios y la consagración de su pueblo.","biblical_meaning_pt":"A perfeição moral de Deus e a consagração de seu povo.","historical_background_en":"Root of 'saint'; applied to God, the Spirit, angels, believers.","historical_background_es":"Raíz de 'santo'; aplicado a Dios, el Espíritu, ángeles, creyentes.","historical_background_pt":"Raiz de 'santo'; aplicado a Deus, ao Espírito, anjos, crentes.","practical_application_en":"Live set apart; pursue purity in a compromising culture.","practical_application_es":"Vive apartado; busca pureza en una cultura de compromiso.","practical_application_pt":"Viva separado; busque pureza numa cultura de compromisso.","related_words":"hagiazō; hagiasmos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"75c0e9a2-1556-48ff-ab9a-83471054fa78","slug":"dikaiosune","order_index":15,"greek":"δικαιοσύνη","transliteration":"dikaiosunē","pronunciation":"dee-kai-oh-SOO-nay","meaning_en":"Righteousness, justice.","meaning_es":"Justicia, rectitud.","meaning_pt":"Justiça, retidão.","biblical_usage_en":"God credits righteousness to those who trust in Jesus.","biblical_usage_es":"Dios acredita justicia a los que confían en Jesús.","biblical_usage_pt":"Deus credita justiça aos que confiam em Jesus.","scripture_refs":"Romans 1:17; 3:21-22; Matthew 5:6","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"dikajoˈsyne","literal_meaning_en":"Conformity to a standard of right.","literal_meaning_es":"Conformidad a una norma de rectitud.","literal_meaning_pt":"Conformidade a uma norma de retidão.","biblical_meaning_en":"The right standing before God, given through Christ by faith.","biblical_meaning_es":"La posición correcta ante Dios, dada por Cristo mediante la fe.","biblical_meaning_pt":"A posição correta diante de Deus, dada por Cristo mediante a fé.","historical_background_en":"Central to Paul's argument in Romans and Galatians.","historical_background_es":"Central en la argumentación de Pablo en Romanos y Gálatas.","historical_background_pt":"Central na argumentação de Paulo em Romanos e Gálatas.","practical_application_en":"Rest in Christ's righteousness, not your performance.","practical_application_es":"Descansa en la justicia de Cristo, no en tu desempeño.","practical_application_pt":"Descanse na justiça de Cristo, não em seu desempenho.","related_words":"dikaioō; dikaios","pronunciation_text":null,"pronunciation_locale":null},
{"id":"6b041301-229a-413c-b563-e4f431f713ab","slug":"kerysso","order_index":16,"greek":"κηρύσσω","transliteration":"kēryssō","pronunciation":"kay-ROOS-soh","meaning_en":"To proclaim, preach, herald.","meaning_es":"Proclamar, predicar, anunciar.","meaning_pt":"Proclamar, pregar, anunciar.","biblical_usage_en":"Used of John the Baptist, Jesus, and the apostles' preaching.","biblical_usage_es":"Usado para la predicación de Juan el Bautista, Jesús y los apóstoles.","biblical_usage_pt":"Usado para a pregação de João Batista, Jesus e os apóstolos.","scripture_refs":"Mark 1:14-15; 2 Timothy 4:2","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"keˈrysːɔː","literal_meaning_en":"To announce publicly as a herald of a king.","literal_meaning_es":"Anunciar públicamente como heraldo de un rey.","literal_meaning_pt":"Anunciar publicamente como arauto de um rei.","biblical_meaning_en":"Public proclamation of the Kingdom and the Gospel.","biblical_meaning_es":"Proclamación pública del Reino y del Evangelio.","biblical_meaning_pt":"Proclamação pública do Reino e do Evangelho.","historical_background_en":"In the Roman world, a kēryx delivered official messages.","historical_background_es":"En el mundo romano, un kēryx entregaba mensajes oficiales.","historical_background_pt":"No mundo romano, um kēryx entregava mensagens oficiais.","practical_application_en":"Speak the good news clearly and boldly.","practical_application_es":"Anuncia las buenas nuevas con claridad y valentía.","practical_application_pt":"Anuncie as boas novas com clareza e coragem.","related_words":"euangelizō; kērygma","pronunciation_text":null,"pronunciation_locale":null},
{"id":"ab32910b-21a5-4f47-9b67-3344b6afc1a4","slug":"euangelion","order_index":17,"greek":"εὐαγγέλιον","transliteration":"euangelion","pronunciation":"yoo-ang-GEL-ee-on","meaning_en":"Good news, gospel.","meaning_es":"Buena nueva, evangelio.","meaning_pt":"Boa nova, evangelho.","biblical_usage_en":"The four Gospels bear this title.","biblical_usage_es":"Los cuatro Evangelios llevan este título.","biblical_usage_pt":"Os quatro Evangelhos levam este título.","scripture_refs":"Mark 1:1; Romans 1:16; 1 Corinthians 15:1-4","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"ewaŋˈɡelion","literal_meaning_en":"A message of good tidings.","literal_meaning_es":"Un mensaje de buenas noticias.","literal_meaning_pt":"Uma mensagem de boas notícias.","biblical_meaning_en":"The announcement of salvation in Jesus Christ.","biblical_meaning_es":"El anuncio de salvación en Jesucristo.","biblical_meaning_pt":"O anúncio de salvação em Jesus Cristo.","historical_background_en":"Originally an imperial announcement of victory or a new emperor.","historical_background_es":"Originalmente un anuncio imperial de victoria o de un nuevo emperador.","historical_background_pt":"Originalmente um anúncio imperial de vitória ou de um novo imperador.","practical_application_en":"Center your life and words on the Gospel of Christ.","practical_application_es":"Centra tu vida y palabras en el Evangelio de Cristo.","practical_application_pt":"Centre sua vida e palavras no Evangelho de Cristo.","related_words":"euangelizō; kērygma","pronunciation_text":null,"pronunciation_locale":null},
{"id":"d4a952e1-9eb8-46a0-b066-6b5fbc4124a4","slug":"basileia","order_index":18,"greek":"βασιλεία","transliteration":"basileia","pronunciation":"bah-see-LAY-ah","meaning_en":"Kingdom, kingship, reign.","meaning_es":"Reino, realeza, reinado.","meaning_pt":"Reino, realeza, reinado.","biblical_usage_en":"'Kingdom of God' / 'Kingdom of Heaven' is Jesus' core message.","biblical_usage_es":"'Reino de Dios' / 'Reino de los Cielos' es el mensaje central de Jesús.","biblical_usage_pt":"'Reino de Deus' / 'Reino dos Céus' é a mensagem central de Jesus.","scripture_refs":"Matthew 6:33; Mark 1:15; Luke 17:20-21","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"basiˈleːa","literal_meaning_en":"The rule or dominion of a king.","literal_meaning_es":"El gobierno o dominio de un rey.","literal_meaning_pt":"O governo ou domínio de um rei.","biblical_meaning_en":"The saving reign of God through Jesus the Messiah.","biblical_meaning_es":"El reinado salvador de Dios por medio de Jesús el Mesías.","biblical_meaning_pt":"O reinado salvador de Deus por meio de Jesus, o Messias.","historical_background_en":"Central Jewish hope rooted in Daniel 2 and the Prophets.","historical_background_es":"Esperanza judía central arraigada en Daniel 2 y los Profetas.","historical_background_pt":"Esperança judaica central enraizada em Daniel 2 e nos Profetas.","practical_application_en":"Seek God's kingdom first in decisions and priorities.","practical_application_es":"Busca primero el reino de Dios en tus decisiones y prioridades.","practical_application_pt":"Busque primeiro o reino de Deus em decisões e prioridades.","related_words":"basileus","pronunciation_text":null,"pronunciation_locale":null},
{"id":"ef7f47b4-aaa1-4fb5-b28d-e96e0c95fa42","slug":"kardia","order_index":19,"greek":"καρδία","transliteration":"kardia","pronunciation":"kar-DEE-ah","meaning_en":"Heart; the inner person, mind, will, emotions.","meaning_es":"Corazón; la persona interior, mente, voluntad, emociones.","meaning_pt":"Coração; a pessoa interior, mente, vontade, emoções.","biblical_usage_en":"Believing 'in the heart' means whole-person trust.","biblical_usage_es":"Creer 'en el corazón' significa confianza integral.","biblical_usage_pt":"Crer 'no coração' significa confiança integral.","scripture_refs":"Romans 10:9-10; Proverbs 4:23; Matthew 5:8","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"karˈdia","literal_meaning_en":"The physical heart, used metaphorically for the center of life.","literal_meaning_es":"El corazón físico, usado metafóricamente como centro de la vida.","literal_meaning_pt":"O coração físico, usado metaforicamente como centro da vida.","biblical_meaning_en":"The seat of faith, thought, and decision before God.","biblical_meaning_es":"La sede de la fe, el pensamiento y la decisión ante Dios.","biblical_meaning_pt":"A sede da fé, do pensamento e da decisão diante de Deus.","historical_background_en":"Semitic idea broader than mere feelings — the whole inner self.","historical_background_es":"Idea semita más amplia que solo sentimientos — todo el ser interior.","historical_background_pt":"Ideia semita mais ampla que só sentimentos — todo o ser interior.","practical_application_en":"Guard your heart; give God your inner life, not only actions.","practical_application_es":"Guarda tu corazón; da a Dios tu vida interior, no solo acciones.","practical_application_pt":"Guarde seu coração; dê a Deus sua vida interior, não só ações.","related_words":"nous; psychē","pronunciation_text":null,"pronunciation_locale":null},
{"id":"91befb8e-d449-4d96-a187-8f02d3888bb9","slug":"psyche","order_index":20,"greek":"ψυχή","transliteration":"psychē","pronunciation":"psoo-KHAY","meaning_en":"Soul, life, self.","meaning_es":"Alma, vida, ser.","meaning_pt":"Alma, vida, ser.","biblical_usage_en":"Jesus warns not to gain the world and lose the psychē.","biblical_usage_es":"Jesús advierte no ganar el mundo y perder la psychē.","biblical_usage_pt":"Jesus adverte não ganhar o mundo e perder a psychē.","scripture_refs":"Mark 8:36-37; Matthew 10:28","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"psyˈkʰe","literal_meaning_en":"The animating life of a creature.","literal_meaning_es":"La vida animadora de una criatura.","literal_meaning_pt":"A vida que anima uma criatura.","biblical_meaning_en":"The whole person considered as a living being before God.","biblical_meaning_es":"La persona entera considerada como un ser viviente ante Dios.","biblical_meaning_pt":"A pessoa inteira considerada como ser vivo diante de Deus.","historical_background_en":"Translates Hebrew 'nephesh'.","historical_background_es":"Traduce el hebreo 'nephesh'.","historical_background_pt":"Traduz o hebraico 'nephesh'.","practical_application_en":"Value your soul above worldly gain.","practical_application_es":"Valora tu alma por encima de la ganancia mundana.","practical_application_pt":"Valorize sua alma acima do ganho mundano.","related_words":"pneuma; nephesh","pronunciation_text":null,"pronunciation_locale":null},
{"id":"2e6d4051-35e9-4d5e-b88e-2e2f6f8aab73","slug":"anastasis","order_index":21,"greek":"ἀνάστασις","transliteration":"anastasis","pronunciation":"ah-NAH-stah-sis","meaning_en":"Resurrection, rising up.","meaning_es":"Resurrección, levantamiento.","meaning_pt":"Ressurreição, levantamento.","biblical_usage_en":"Foundation of Christian faith: 'If Christ has not been raised...'","biblical_usage_es":"Fundamento de la fe cristiana: 'Si Cristo no ha resucitado...'","biblical_usage_pt":"Fundamento da fé cristã: 'Se Cristo não ressuscitou...'","scripture_refs":"1 Corinthians 15; John 11:25; Acts 17:31","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"aˈnastasis","literal_meaning_en":"A standing up again.","literal_meaning_es":"Un ponerse de pie otra vez.","literal_meaning_pt":"Um levantar-se novamente.","biblical_meaning_en":"Bodily rising from the dead, especially of Christ.","biblical_meaning_es":"Levantamiento corporal de entre los muertos, especialmente de Cristo.","biblical_meaning_pt":"Levantamento corporal dentre os mortos, especialmente de Cristo.","historical_background_en":"Jewish hope debated by Pharisees vs. Sadducees.","historical_background_es":"Esperanza judía debatida por fariseos y saduceos.","historical_background_pt":"Esperança judaica debatida por fariseus e saduceus.","practical_application_en":"Live with resurrection hope shaping today's choices.","practical_application_es":"Vive con la esperanza de la resurrección moldeando tus decisiones hoy.","practical_application_pt":"Viva com a esperança da ressurreição moldando suas escolhas hoje.","related_words":"egeirō","pronunciation_text":null,"pronunciation_locale":null},
{"id":"d6571158-de7b-4325-8613-d50e7850c136","slug":"parousia","order_index":22,"greek":"παρουσία","transliteration":"parousia","pronunciation":"pah-roo-SEE-ah","meaning_en":"Coming, arrival, presence.","meaning_es":"Venida, llegada, presencia.","meaning_pt":"Vinda, chegada, presença.","biblical_usage_en":"Applied by the apostles to Christ's Second Coming.","biblical_usage_es":"Aplicado por los apóstoles a la Segunda Venida de Cristo.","biblical_usage_pt":"Aplicado pelos apóstolos à Segunda Vinda de Cristo.","scripture_refs":"Matthew 24:27; 1 Thessalonians 4:15; 2 Peter 3:4","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"paruˈsia","literal_meaning_en":"Being present or arriving.","literal_meaning_es":"Estar presente o llegar.","literal_meaning_pt":"Estar presente ou chegar.","biblical_meaning_en":"The visible return of Jesus Christ in glory.","biblical_meaning_es":"El regreso visible de Jesucristo en gloria.","biblical_meaning_pt":"O retorno visível de Jesus Cristo em glória.","historical_background_en":"Used for an official royal visit in the ancient world.","historical_background_es":"Usado para una visita real oficial en el mundo antiguo.","historical_background_pt":"Usado para uma visita real oficial no mundo antigo.","practical_application_en":"Live ready, watchful, and hopeful for Christ's return.","practical_application_es":"Vive preparado, vigilante y esperanzado por el regreso de Cristo.","practical_application_pt":"Viva pronto, vigilante e esperançoso pela volta de Cristo.","related_words":"epiphaneia","pronunciation_text":null,"pronunciation_locale":null},
{"id":"39cb6157-2ab5-4cda-9bbf-11065bfd1172","slug":"koinonia","order_index":23,"greek":"κοινωνία","transliteration":"koinōnia","pronunciation":"koy-noh-NEE-ah","meaning_en":"Fellowship, sharing, participation, communion.","meaning_es":"Comunión, participación, compañerismo.","meaning_pt":"Comunhão, participação, companheirismo.","biblical_usage_en":"Describes the early church's shared life in Acts 2.","biblical_usage_es":"Describe la vida compartida de la iglesia primitiva en Hechos 2.","biblical_usage_pt":"Descreve a vida compartilhada da igreja primitiva em Atos 2.","scripture_refs":"Acts 2:42; 1 John 1:3; Philippians 1:5","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"kojnoˈnia","literal_meaning_en":"Having something in common.","literal_meaning_es":"Tener algo en común.","literal_meaning_pt":"Ter algo em comum.","biblical_meaning_en":"Shared life with God and with fellow believers.","biblical_meaning_es":"Vida compartida con Dios y con los demás creyentes.","biblical_meaning_pt":"Vida compartilhada com Deus e com outros crentes.","historical_background_en":"Common in Greek clubs and business partnerships.","historical_background_es":"Común en clubes y sociedades comerciales griegas.","historical_background_pt":"Comum em clubes e sociedades comerciais gregas.","practical_application_en":"Invest deeply in Christian community, not just attendance.","practical_application_es":"Invierte profundamente en comunidad cristiana, no solo asistas.","practical_application_pt":"Invista profundamente na comunidade cristã, não apenas frequente.","related_words":"koinōnos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"2ca465a6-6574-4e69-8681-eb654d5ba001","slug":"hupomone","order_index":24,"greek":"ὑπομονή","transliteration":"hupomonē","pronunciation":"hoo-po-mo-NAY","meaning_en":"Endurance, steadfastness, patient hope.","meaning_es":"Perseverancia, firmeza, esperanza paciente.","meaning_pt":"Perseverança, firmeza, esperança paciente.","biblical_usage_en":"Trials produce hupomonē, which produces character.","biblical_usage_es":"Las pruebas producen hupomonē, que produce carácter.","biblical_usage_pt":"As provações produzem hupomonē, que produz caráter.","scripture_refs":"Romans 5:3-4; James 1:3-4; Revelation 14:12","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"hypomoˈne","literal_meaning_en":"Remaining under a load without collapsing.","literal_meaning_es":"Permanecer bajo una carga sin colapsar.","literal_meaning_pt":"Permanecer sob uma carga sem colapsar.","biblical_meaning_en":"Faithful endurance under trial, anchored in hope.","biblical_meaning_es":"Perseverancia fiel bajo la prueba, anclada en la esperanza.","biblical_meaning_pt":"Perseverança fiel sob a provação, ancorada na esperança.","historical_background_en":"Highly valued Stoic virtue; reshaped by Christian hope.","historical_background_es":"Virtud estoica muy valorada; reformada por la esperanza cristiana.","historical_background_pt":"Virtude estoica muito valorizada; reformulada pela esperança cristã.","practical_application_en":"Ask God for endurance in this present season.","practical_application_es":"Pide a Dios perseverancia en esta temporada actual.","practical_application_pt":"Peça a Deus perseverança nesta temporada atual.","related_words":"makrothumia","pronunciation_text":null,"pronunciation_locale":null},
{"id":"4491e688-75c6-4417-b2ed-c0ca043b3288","slug":"charisma","order_index":25,"greek":"χάρισμα","transliteration":"charisma","pronunciation":"KAH-ris-mah","meaning_en":"Gift of grace, spiritual gift.","meaning_es":"Don de gracia, don espiritual.","meaning_pt":"Dom da graça, dom espiritual.","biblical_usage_en":"Paul lists varieties of gifts in Romans 12 and 1 Corinthians 12.","biblical_usage_es":"Pablo enumera variedad de dones en Romanos 12 y 1 Corintios 12.","biblical_usage_pt":"Paulo lista variedade de dons em Romanos 12 e 1 Coríntios 12.","scripture_refs":"Romans 12:6; 1 Corinthians 12:4; 1 Peter 4:10","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"ˈkʰarisma","literal_meaning_en":"A free gift given from favor.","literal_meaning_es":"Un regalo gratuito dado por favor.","literal_meaning_pt":"Um presente gratuito dado por favor.","biblical_meaning_en":"A Spirit-given ability to serve God's people.","biblical_meaning_es":"Una habilidad dada por el Espíritu para servir al pueblo de Dios.","biblical_meaning_pt":"Uma capacidade dada pelo Espírito para servir o povo de Deus.","historical_background_en":"Related to 'charis' — undeserved kindness.","historical_background_es":"Relacionado con 'charis' — bondad inmerecida.","historical_background_pt":"Relacionado a 'charis' — bondade imerecida.","practical_application_en":"Discover and use your gifts to serve others in love.","practical_application_es":"Descubre y usa tus dones para servir a otros en amor.","practical_application_pt":"Descubra e use seus dons para servir os outros em amor.","related_words":"charis; pneumatikos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"52d098ee-b1ed-4c17-9f5d-372b0d22436d","slug":"prosuchomai","order_index":26,"greek":"προσεύχομαι","transliteration":"proseuchomai","pronunciation":"pros-YOO-kho-my","meaning_en":"To pray, address God.","meaning_es":"Orar, dirigirse a Dios.","meaning_pt":"Orar, dirigir-se a Deus.","biblical_usage_en":"Used across the Gospels, especially of Jesus withdrawing to pray.","biblical_usage_es":"Usado en los Evangelios, especialmente de Jesús retirándose a orar.","biblical_usage_pt":"Usado nos Evangelhos, especialmente de Jesus retirando-se para orar.","scripture_refs":"Matthew 6:9; Luke 5:16; 1 Thessalonians 5:17","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"proˈsewkʰomai","literal_meaning_en":"To offer a prayer or wish toward.","literal_meaning_es":"Ofrecer una oración o deseo hacia.","literal_meaning_pt":"Oferecer uma oração ou desejo em direção a.","biblical_meaning_en":"Personal, direct communication with God as Father.","biblical_meaning_es":"Comunicación personal y directa con Dios como Padre.","biblical_meaning_pt":"Comunicação pessoal e direta com Deus como Pai.","historical_background_en":"Jesus modeled and taught constant prayer.","historical_background_es":"Jesús modeló y enseñó la oración constante.","historical_background_pt":"Jesus modelou e ensinou a oração constante.","practical_application_en":"Set fixed times to pray and cultivate an ongoing conversation with God.","practical_application_es":"Fija tiempos para orar y cultiva una conversación continua con Dios.","practical_application_pt":"Estabeleça horários para orar e cultive uma conversa contínua com Deus.","related_words":"proseuchē; deēsis","pronunciation_text":null,"pronunciation_locale":null},
{"id":"60fff97e-6814-4b79-b192-d08ab13d2029","slug":"didaskalos","order_index":27,"greek":"διδάσκαλος","transliteration":"didaskalos","pronunciation":"dee-DAH-skah-los","meaning_en":"Teacher.","meaning_es":"Maestro.","meaning_pt":"Mestre.","biblical_usage_en":"Jesus is called 'Teacher' throughout the Gospels.","biblical_usage_es":"Jesús es llamado 'Maestro' a lo largo de los Evangelios.","biblical_usage_pt":"Jesus é chamado 'Mestre' ao longo dos Evangelhos.","scripture_refs":"Matthew 23:8; John 13:13; James 3:1","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"diˈdaskalos","literal_meaning_en":"One who teaches.","literal_meaning_es":"El que enseña.","literal_meaning_pt":"Aquele que ensina.","biblical_meaning_en":"A title of respect for Jesus and for teachers of Scripture.","biblical_meaning_es":"Título de respeto para Jesús y para maestros de la Escritura.","biblical_meaning_pt":"Título de respeito para Jesus e para mestres da Escritura.","historical_background_en":"Greek equivalent of the Hebrew 'Rabbi'.","historical_background_es":"Equivalente griego del hebreo 'Rabí'.","historical_background_pt":"Equivalente grego do hebraico 'Rabi'.","practical_application_en":"Sit as a learner under Christ before teaching others.","practical_application_es":"Siéntate como aprendiz bajo Cristo antes de enseñar a otros.","practical_application_pt":"Sente-se como aprendiz sob Cristo antes de ensinar outros.","related_words":"rabbi; didachē","pronunciation_text":null,"pronunciation_locale":null},
{"id":"97696f39-acaf-4b2e-9fe6-16121bc1eea7","slug":"hamartia","order_index":28,"greek":"ἁμαρτία","transliteration":"hamartia","pronunciation":"hah-mar-TEE-ah","meaning_en":"Sin, missing the mark.","meaning_es":"Pecado, errar el blanco.","meaning_pt":"Pecado, errar o alvo.","biblical_usage_en":"Universal condition remedied only by Christ.","biblical_usage_es":"Condición universal remediada solo por Cristo.","biblical_usage_pt":"Condição universal remediada apenas por Cristo.","scripture_refs":"Romans 3:23; 1 John 1:8-9","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"hamarˈtia","literal_meaning_en":"Missing a target.","literal_meaning_es":"Fallar un blanco.","literal_meaning_pt":"Errar um alvo.","biblical_meaning_en":"Failing to hit God's standard, both in act and nature.","biblical_meaning_es":"No alcanzar la norma de Dios, en acto y en naturaleza.","biblical_meaning_pt":"Não atingir o padrão de Deus, em ato e em natureza.","historical_background_en":"Archery term repurposed to describe moral failure.","historical_background_es":"Término de tiro con arco usado para describir el fallo moral.","historical_background_pt":"Termo de arco e flecha usado para descrever a falha moral.","practical_application_en":"Confess and repent honestly; run to Christ's grace.","practical_application_es":"Confiesa y arrepiéntete con honestidad; corre a la gracia de Cristo.","practical_application_pt":"Confesse e arrependa-se com honestidade; corra para a graça de Cristo.","related_words":"hamartōlos; parabasis","pronunciation_text":null,"pronunciation_locale":null},
{"id":"17d84d58-4742-4cf3-b9d5-61361f38d1db","slug":"phos","order_index":29,"greek":"φῶς","transliteration":"phōs","pronunciation":"FOHSS","meaning_en":"Light.","meaning_es":"Luz.","meaning_pt":"Luz.","biblical_usage_en":"Jesus: 'I am the light of the world.' Believers reflect this light.","biblical_usage_es":"Jesús: 'Yo soy la luz del mundo.' Los creyentes reflejan esta luz.","biblical_usage_pt":"Jesus: 'Eu sou a luz do mundo.' Os crentes refletem esta luz.","scripture_refs":"John 8:12; Matthew 5:14; 1 John 1:5","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"pʰɔːs","literal_meaning_en":"Physical light that illuminates.","literal_meaning_es":"Luz física que ilumina.","literal_meaning_pt":"Luz física que ilumina.","biblical_meaning_en":"Truth, holiness, and the presence of God.","biblical_meaning_es":"Verdad, santidad y la presencia de Dios.","biblical_meaning_pt":"Verdade, santidade e a presença de Deus.","historical_background_en":"Recurring biblical image of God's self-revelation.","historical_background_es":"Imagen bíblica recurrente de la autorevelación de Dios.","historical_background_pt":"Imagem bíblica recorrente da autorrevelação de Deus.","practical_application_en":"Walk in truth openly; refuse hidden compromises.","practical_application_es":"Camina en la verdad abiertamente; rechaza compromisos ocultos.","practical_application_pt":"Ande na verdade abertamente; rejeite compromissos ocultos.","related_words":"skotia","pronunciation_text":null,"pronunciation_locale":null},
{"id":"db2e243f-86fd-4ac2-bbb2-6a4022de3d82","slug":"aletheia","order_index":30,"greek":"ἀλήθεια","transliteration":"alētheia","pronunciation":"ah-LAY-thay-ah","meaning_en":"Truth, reality.","meaning_es":"Verdad, realidad.","meaning_pt":"Verdade, realidade.","biblical_usage_en":"Jesus: 'I am the way, the truth, and the life.'","biblical_usage_es":"Jesús: 'Yo soy el camino, la verdad y la vida.'","biblical_usage_pt":"Jesus: 'Eu sou o caminho, a verdade e a vida.'","scripture_refs":"John 14:6; John 8:32; Ephesians 4:15","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"greek","ipa":"aˈleːtʰeja","literal_meaning_en":"That which is not hidden; what is real.","literal_meaning_es":"Lo que no está oculto; lo que es real.","literal_meaning_pt":"O que não está oculto; o que é real.","biblical_meaning_en":"God's revealed truth centered in Jesus.","biblical_meaning_es":"La verdad revelada de Dios centrada en Jesús.","biblical_meaning_pt":"A verdade revelada de Deus centrada em Jesus.","historical_background_en":"Contrasted with pseudos (falsehood) throughout Scripture.","historical_background_es":"Contrastado con pseudos (falsedad) a lo largo de la Escritura.","historical_background_pt":"Contrastado com pseudos (falsidade) ao longo da Escritura.","practical_application_en":"Anchor your identity and choices in God's truth, not culture's shifts.","practical_application_es":"Ancla tu identidad y decisiones en la verdad de Dios, no en la cultura.","practical_application_pt":"Ancore sua identidade e escolhas na verdade de Deus, não na cultura.","related_words":"alēthinos; pseudos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"2fb6f333-22ae-40a9-97dc-d55c3ddf46ff","slug":"elohim","order_index":1,"greek":"אֱלֹהִים","transliteration":"Elohim","pronunciation":"el-oh-HEEM","meaning_en":"God; the mighty one, plural of majesty.","meaning_es":"Dios; el poderoso, plural de majestad.","meaning_pt":"Deus; o poderoso, plural de majestade.","biblical_usage_en":"Used over 2,500 times in the Old Testament.","biblical_usage_es":"Usado más de 2.500 veces en el Antiguo Testamento.","biblical_usage_pt":"Usado mais de 2.500 vezes no Antigo Testamento.","scripture_refs":"Genesis 1:1; Psalm 19:1; Isaiah 40:28","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔɛloˈhim","literal_meaning_en":"Plural form meaning 'gods' but used of the one true God.","literal_meaning_es":"Forma plural que significa 'dioses' pero usada del único Dios verdadero.","literal_meaning_pt":"Forma plural que significa 'deuses' mas usada do único Deus verdadeiro.","biblical_meaning_en":"The Creator God of Israel, sovereign and majestic.","biblical_meaning_es":"El Dios Creador de Israel, soberano y majestuoso.","biblical_meaning_pt":"O Deus Criador de Israel, soberano e majestoso.","historical_background_en":"First name for God in the Bible (Genesis 1:1).","historical_background_es":"Primer nombre de Dios en la Biblia (Génesis 1:1).","historical_background_pt":"Primeiro nome de Deus na Bíblia (Gênesis 1:1).","practical_application_en":"Worship God as sovereign Creator over every detail of life.","practical_application_es":"Adora a Dios como Creador soberano sobre cada detalle de la vida.","practical_application_pt":"Adore a Deus como Criador soberano sobre cada detalhe da vida.","related_words":"El; Eloah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"2287db3a-02d3-4c9a-a536-a51327da26cb","slug":"yhwh","order_index":2,"greek":"יהוה","transliteration":"YHWH / Yahweh","pronunciation":"YAH-weh","meaning_en":"The LORD; God's personal covenant name.","meaning_es":"El SEÑOR; el nombre personal del pacto de Dios.","meaning_pt":"O SENHOR; o nome pessoal da aliança de Deus.","biblical_usage_en":"Written 'LORD' in English Bibles out of reverence.","biblical_usage_es":"Escrito 'SEÑOR' en Biblias en español por reverencia.","biblical_usage_pt":"Escrito 'SENHOR' em Bíblias em português por reverência.","scripture_refs":"Exodus 3:14-15; Deuteronomy 6:4; Isaiah 42:8","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"jahˈwe","literal_meaning_en":"'I AM WHO I AM' — the self-existent One.","literal_meaning_es":"'YO SOY EL QUE SOY' — el que existe por sí mismo.","literal_meaning_pt":"'EU SOU O QUE SOU' — aquele que existe por si mesmo.","biblical_meaning_en":"The unchanging, faithful God who redeems His people.","biblical_meaning_es":"El Dios inmutable y fiel que redime a su pueblo.","biblical_meaning_pt":"O Deus imutável e fiel que redime seu povo.","historical_background_en":"Revealed to Moses at the burning bush.","historical_background_es":"Revelado a Moisés en la zarza ardiente.","historical_background_pt":"Revelado a Moisés na sarça ardente.","practical_application_en":"Trust God's unchanging faithfulness across every season.","practical_application_es":"Confía en la fidelidad inmutable de Dios en cada temporada.","practical_application_pt":"Confie na fidelidade imutável de Deus em cada temporada.","related_words":"Adonai; Elohim","pronunciation_text":null,"pronunciation_locale":null},
{"id":"251a2f1b-2bff-417c-8e0d-91329ab406bb","slug":"adonai","order_index":3,"greek":"אֲדֹנָי","transliteration":"Adonai","pronunciation":"ah-doh-NAI","meaning_en":"Lord, Master.","meaning_es":"Señor, Amo.","meaning_pt":"Senhor, Mestre.","biblical_usage_en":"Common address in Psalms and prayers.","biblical_usage_es":"Dirección común en los Salmos y oraciones.","biblical_usage_pt":"Endereço comum nos Salmos e nas orações.","scripture_refs":"Genesis 15:2; Psalm 8:1; Isaiah 6:1","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔadoˈnaj","literal_meaning_en":"'My Lord'; a plural of majesty.","literal_meaning_es":"'Mi Señor'; un plural de majestad.","literal_meaning_pt":"'Meu Senhor'; um plural de majestade.","biblical_meaning_en":"God as sovereign owner and ruler of all.","biblical_meaning_es":"Dios como dueño soberano y gobernante de todo.","biblical_meaning_pt":"Deus como dono soberano e governante de tudo.","historical_background_en":"Spoken by Jews in place of YHWH out of reverence.","historical_background_es":"Pronunciado por los judíos en lugar de YHWH por reverencia.","historical_background_pt":"Pronunciado pelos judeus em lugar de YHWH por reverência.","practical_application_en":"Submit daily decisions to God as Lord, not consult Him as advisor.","practical_application_es":"Somete tus decisiones diarias a Dios como Señor, no lo consultes como asesor.","practical_application_pt":"Submeta suas decisões diárias a Deus como Senhor, não o consulte como conselheiro.","related_words":"YHWH","pronunciation_text":null,"pronunciation_locale":null},
{"id":"a36b0fb1-2d41-43ec-b87c-8f29485789f9","slug":"el-shaddai","order_index":4,"greek":"אֵל שַׁדַּי","transliteration":"El Shaddai","pronunciation":"el shah-DAI","meaning_en":"God Almighty.","meaning_es":"Dios Todopoderoso.","meaning_pt":"Deus Todo-Poderoso.","biblical_usage_en":"Used when God confirms covenant with Abraham.","biblical_usage_es":"Usado cuando Dios confirma el pacto con Abraham.","biblical_usage_pt":"Usado quando Deus confirma a aliança com Abraão.","scripture_refs":"Genesis 17:1; Exodus 6:3; Psalm 91:1","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔel ʃaˈdaj","literal_meaning_en":"Traditionally 'God of the mountain' or 'God Almighty'.","literal_meaning_es":"Tradicionalmente 'Dios de la montaña' o 'Dios Todopoderoso'.","literal_meaning_pt":"Tradicionalmente 'Deus da montanha' ou 'Deus Todo-Poderoso'.","biblical_meaning_en":"God's all-sufficient power to keep His promises.","biblical_meaning_es":"El poder todo-suficiente de Dios para cumplir sus promesas.","biblical_meaning_pt":"O poder todo-suficiente de Deus para cumprir suas promessas.","historical_background_en":"The name by which God appeared to the patriarchs.","historical_background_es":"El nombre con el que Dios apareció a los patriarcas.","historical_background_pt":"O nome pelo qual Deus apareceu aos patriarcas.","practical_application_en":"Trust God's power in impossible situations.","practical_application_es":"Confía en el poder de Dios en situaciones imposibles.","practical_application_pt":"Confie no poder de Deus em situações impossíveis.","related_words":"El Elyon","pronunciation_text":null,"pronunciation_locale":null},
{"id":"f5aa9f82-8a89-4d48-ac41-6d086cbdc4e4","slug":"el-elyon","order_index":5,"greek":"אֵל עֶלְיוֹן","transliteration":"El Elyon","pronunciation":"el el-YOHN","meaning_en":"God Most High.","meaning_es":"Dios Altísimo.","meaning_pt":"Deus Altíssimo.","biblical_usage_en":"Emphasizes God's supremacy over rival gods.","biblical_usage_es":"Enfatiza la supremacía de Dios sobre dioses rivales.","biblical_usage_pt":"Enfatiza a supremacia de Deus sobre deuses rivais.","scripture_refs":"Genesis 14:18-20; Psalm 91:1; Daniel 4:17","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔel ʕɛlˈjon","literal_meaning_en":"The exalted One above all.","literal_meaning_es":"El exaltado sobre todos.","literal_meaning_pt":"O exaltado acima de todos.","biblical_meaning_en":"God as supreme over all powers, gods, and nations.","biblical_meaning_es":"Dios como supremo sobre todos los poderes, dioses y naciones.","biblical_meaning_pt":"Deus como supremo sobre todos os poderes, deuses e nações.","historical_background_en":"First used by Melchizedek blessing Abram.","historical_background_es":"Usado por primera vez por Melquisedec bendiciendo a Abram.","historical_background_pt":"Usado pela primeira vez por Melquisedeque abençoando Abrão.","practical_application_en":"Fear no rival power; God reigns above all.","practical_application_es":"No temas a ningún poder rival; Dios reina sobre todo.","practical_application_pt":"Não tema poder rival algum; Deus reina sobre tudo.","related_words":"El Shaddai","pronunciation_text":null,"pronunciation_locale":null},
{"id":"5b04ae25-ff10-4281-8c45-1dc41bbdd57b","slug":"ruach","order_index":6,"greek":"רוּחַ","transliteration":"Ruach","pronunciation":"ROO-akh","meaning_en":"Spirit, breath, wind.","meaning_es":"Espíritu, aliento, viento.","meaning_pt":"Espírito, sopro, vento.","biblical_usage_en":"Same word used for wind, breath, and Spirit — context decides.","biblical_usage_es":"La misma palabra se usa para viento, aliento y Espíritu — el contexto decide.","biblical_usage_pt":"A mesma palavra é usada para vento, sopro e Espírito — o contexto decide.","scripture_refs":"Genesis 1:2; Ezekiel 37:9-10; Joel 2:28","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ˈruaχ","literal_meaning_en":"Moving air — wind or breath of life.","literal_meaning_es":"Aire en movimiento — viento o aliento de vida.","literal_meaning_pt":"Ar em movimento — vento ou sopro de vida.","biblical_meaning_en":"The Spirit of God who creates, empowers, and dwells with His people.","biblical_meaning_es":"El Espíritu de Dios que crea, capacita y habita con su pueblo.","biblical_meaning_pt":"O Espírito de Deus que cria, capacita e habita com seu povo.","historical_background_en":"Ruach Elohim hovers over the waters in Genesis 1.","historical_background_es":"Ruach Elohim se movía sobre las aguas en Génesis 1.","historical_background_pt":"Ruach Elohim pairava sobre as águas em Gênesis 1.","practical_application_en":"Yield to the Spirit's work of renewal and empowerment.","practical_application_es":"Ríndete a la obra del Espíritu de renovación y capacitación.","practical_application_pt":"Renda-se à obra do Espírito de renovação e capacitação.","related_words":"neshamah; pneuma","pronunciation_text":null,"pronunciation_locale":null},
{"id":"30411a5f-5b27-4ef9-ba38-be698e3183d8","slug":"nephesh","order_index":7,"greek":"נֶפֶשׁ","transliteration":"Nephesh","pronunciation":"NEH-fesh","meaning_en":"Soul, life, person, being.","meaning_es":"Alma, vida, persona, ser.","meaning_pt":"Alma, vida, pessoa, ser.","biblical_usage_en":"God formed man and he became a 'living nephesh'.","biblical_usage_es":"Dios formó al hombre y este se convirtió en 'nephesh viviente'.","biblical_usage_pt":"Deus formou o homem e ele se tornou 'nephesh vivente'.","scripture_refs":"Genesis 2:7; Psalm 42:1-2; Leviticus 17:11","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ˈnefeʃ","literal_meaning_en":"Throat, breath — the life within a creature.","literal_meaning_es":"Garganta, aliento — la vida dentro de una criatura.","literal_meaning_pt":"Garganta, sopro — a vida dentro de uma criatura.","biblical_meaning_en":"The whole living person, not a separate 'ghost' inside.","biblical_meaning_es":"La persona viviente entera, no un 'fantasma' interior separado.","biblical_meaning_pt":"A pessoa viva inteira, não um 'fantasma' interior separado.","historical_background_en":"Reflects Hebrew view of the human as a unified being.","historical_background_es":"Refleja la visión hebrea del ser humano como ser unificado.","historical_background_pt":"Reflete a visão hebraica do ser humano como ser unificado.","practical_application_en":"Care for your whole self before God — body, mind, and heart.","practical_application_es":"Cuida a toda tu persona ante Dios — cuerpo, mente y corazón.","practical_application_pt":"Cuide de toda a sua pessoa diante de Deus — corpo, mente e coração.","related_words":"ruach; psychē","pronunciation_text":null,"pronunciation_locale":null},
{"id":"489b331e-b635-4aeb-b294-9c09296a7cae","slug":"hesed","order_index":8,"greek":"חֶסֶד","transliteration":"Hesed","pronunciation":"KHEH-sed","meaning_en":"Steadfast love, loyal covenant kindness.","meaning_es":"Amor firme, bondad leal del pacto.","meaning_pt":"Amor firme, bondade leal da aliança.","biblical_usage_en":"Foundation of God's dealings with Israel and the church.","biblical_usage_es":"Fundamento del trato de Dios con Israel y la iglesia.","biblical_usage_pt":"Fundamento do trato de Deus com Israel e a igreja.","scripture_refs":"Psalm 136; Exodus 34:6-7; Lamentations 3:22-23","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ˈχesed","literal_meaning_en":"Loyalty grounded in a committed relationship.","literal_meaning_es":"Lealtad basada en una relación comprometida.","literal_meaning_pt":"Lealdade baseada num relacionamento comprometido.","biblical_meaning_en":"God's covenant faithfulness that never fails.","biblical_meaning_es":"La fidelidad de Dios al pacto que nunca falla.","biblical_meaning_pt":"A fidelidade de Deus à aliança que nunca falha.","historical_background_en":"Central theme of Psalms (136 uses 'hesed' 26 times).","historical_background_es":"Tema central de los Salmos (el 136 usa 'hesed' 26 veces).","historical_background_pt":"Tema central dos Salmos (o 136 usa 'hesed' 26 vezes).","practical_application_en":"Return God's loyal love with loyal, committed obedience.","practical_application_es":"Corresponde al amor leal de Dios con obediencia leal y comprometida.","practical_application_pt":"Corresponda ao amor leal de Deus com obediência leal e comprometida.","related_words":"emet; rachamim","pronunciation_text":null,"pronunciation_locale":null},
{"id":"9aad1e12-4dcc-4969-bc1e-2e5a7bb31924","slug":"emunah","order_index":9,"greek":"אֱמוּנָה","transliteration":"Emunah","pronunciation":"eh-moo-NAH","meaning_en":"Faithfulness, faith, firmness.","meaning_es":"Fidelidad, fe, firmeza.","meaning_pt":"Fidelidade, fé, firmeza.","biblical_usage_en":"'The righteous shall live by his emunah' (Hab. 2:4).","biblical_usage_es":"'El justo por su emunah vivirá' (Hab. 2:4).","biblical_usage_pt":"'O justo viverá pela sua emunah' (Hab. 2:4).","scripture_refs":"Habakkuk 2:4; Deuteronomy 32:4; Lamentations 3:23","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔɛmuˈna","literal_meaning_en":"Firmness, reliability.","literal_meaning_es":"Firmeza, confiabilidad.","literal_meaning_pt":"Firmeza, confiabilidade.","biblical_meaning_en":"Faith as trust that rests on the trustworthiness of God.","biblical_meaning_es":"Fe como confianza que descansa en la fidelidad de Dios.","biblical_meaning_pt":"Fé como confiança que repousa na fidelidade de Deus.","historical_background_en":"Root of 'Amen' — 'so be it, it is firm'.","historical_background_es":"Raíz de 'Amén' — 'así sea, es firme'.","historical_background_pt":"Raiz de 'Amém' — 'assim seja, é firme'.","practical_application_en":"Practice steady faith — small acts of trust each day.","practical_application_es":"Practica una fe firme — pequeños actos de confianza cada día.","practical_application_pt":"Pratique uma fé firme — pequenos atos de confiança a cada dia.","related_words":"aman; pistis","pronunciation_text":null,"pronunciation_locale":null},
{"id":"e1dcf0dc-d312-49aa-95ad-59ce07963655","slug":"torah","order_index":10,"greek":"תּוֹרָה","transliteration":"Torah","pronunciation":"toh-RAH","meaning_en":"Instruction, teaching, law.","meaning_es":"Instrucción, enseñanza, ley.","meaning_pt":"Instrução, ensino, lei.","biblical_usage_en":"More than 'law' — full formation for covenant life.","biblical_usage_es":"Más que 'ley' — formación integral para la vida del pacto.","biblical_usage_pt":"Mais que 'lei' — formação integral para a vida da aliança.","scripture_refs":"Psalm 1:2; Psalm 119; Matthew 5:17","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"toˈra","literal_meaning_en":"Guidance from a teacher or parent.","literal_meaning_es":"Guía de un maestro o padre.","literal_meaning_pt":"Orientação de um mestre ou pai.","biblical_meaning_en":"God's covenant teaching for the life of His people.","biblical_meaning_es":"La enseñanza del pacto de Dios para la vida de su pueblo.","biblical_meaning_pt":"O ensino da aliança de Deus para a vida de seu povo.","historical_background_en":"Refers specifically to the first five books of the Bible.","historical_background_es":"Se refiere específicamente a los primeros cinco libros de la Biblia.","historical_background_pt":"Refere-se especificamente aos cinco primeiros livros da Bíblia.","practical_application_en":"Meditate on Scripture daily as loving instruction, not burden.","practical_application_es":"Medita en la Escritura a diario como instrucción amorosa, no carga.","practical_application_pt":"Medite nas Escrituras diariamente como instrução amorosa, não carga.","related_words":"mitzvah; halakhah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"6e642652-3550-480f-a082-bd03f9ac1944","slug":"shalom","order_index":11,"greek":"שָׁלוֹם","transliteration":"Shalom","pronunciation":"shah-LOME","meaning_en":"Peace, wholeness, well-being.","meaning_es":"Paz, plenitud, bienestar.","meaning_pt":"Paz, plenitude, bem-estar.","biblical_usage_en":"The Messiah is called 'Prince of Shalom' (Isaiah 9:6).","biblical_usage_es":"El Mesías es llamado 'Príncipe de Shalom' (Isaías 9:6).","biblical_usage_pt":"O Messias é chamado 'Príncipe de Shalom' (Isaías 9:6).","scripture_refs":"Numbers 6:24-26; Isaiah 9:6; John 14:27","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʃaˈlom","literal_meaning_en":"Complete, whole, unbroken.","literal_meaning_es":"Completo, íntegro, sin quebrar.","literal_meaning_pt":"Completo, íntegro, sem quebra.","biblical_meaning_en":"The full flourishing God intends for His creation.","biblical_meaning_es":"El pleno florecimiento que Dios desea para su creación.","biblical_meaning_pt":"O pleno florescimento que Deus deseja para sua criação.","historical_background_en":"Standard Hebrew greeting and farewell.","historical_background_es":"Saludo y despedida hebreos estándar.","historical_background_pt":"Saudação e despedida padrão em hebraico.","practical_application_en":"Be a peacemaker — restoring wholeness in relationships.","practical_application_es":"Sé un pacificador — restaurando plenitud en las relaciones.","practical_application_pt":"Seja um pacificador — restaurando plenitude nas relações.","related_words":"shalem","pronunciation_text":null,"pronunciation_locale":null},
{"id":"bc8395b9-c7d8-461e-ad4c-46523acf2943","slug":"mashiach","order_index":12,"greek":"מָשִׁיחַ","transliteration":"Mashiach","pronunciation":"mah-SHEE-akh","meaning_en":"Messiah, Anointed One.","meaning_es":"Mesías, Ungido.","meaning_pt":"Messias, Ungido.","biblical_usage_en":"Christos in Greek — the New Testament title for Jesus.","biblical_usage_es":"Christos en griego — el título del Nuevo Testamento para Jesús.","biblical_usage_pt":"Christos em grego — o título do Novo Testamento para Jesus.","scripture_refs":"Daniel 9:25-26; Psalm 2:2; John 1:41","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"maˈʃiaχ","literal_meaning_en":"One smeared with oil.","literal_meaning_es":"Uno ungido con aceite.","literal_meaning_pt":"Alguém ungido com óleo.","biblical_meaning_en":"The promised King, Priest, and Prophet — fulfilled in Jesus.","biblical_meaning_es":"El Rey, Sacerdote y Profeta prometido — cumplido en Jesús.","biblical_meaning_pt":"O Rei, Sacerdote e Profeta prometido — cumprido em Jesus.","historical_background_en":"Kings and priests were anointed with oil in Israel.","historical_background_es":"Los reyes y sacerdotes eran ungidos con aceite en Israel.","historical_background_pt":"Reis e sacerdotes eram ungidos com óleo em Israel.","practical_application_en":"Bow to Jesus as your anointed King, Priest, and Prophet.","practical_application_es":"Inclínate ante Jesús como tu Rey, Sacerdote y Profeta ungido.","practical_application_pt":"Curve-se a Jesus como seu Rei, Sacerdote e Profeta ungido.","related_words":"Christos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"9f860d37-f867-4c9b-b448-04018b244e1b","slug":"goel","order_index":13,"greek":"גֹּאֵל","transliteration":"Go'el","pronunciation":"goh-EL","meaning_en":"Kinsman-redeemer.","meaning_es":"Pariente-redentor.","meaning_pt":"Parente-redentor.","biblical_usage_en":"Foreshadows Christ as the ultimate Redeemer.","biblical_usage_es":"Prefigura a Cristo como el Redentor supremo.","biblical_usage_pt":"Prefigura a Cristo como o Redentor supremo.","scripture_refs":"Ruth 4; Job 19:25; Isaiah 41:14","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ɡoˈʔel","literal_meaning_en":"A near relative who redeems.","literal_meaning_es":"Un pariente cercano que redime.","literal_meaning_pt":"Um parente próximo que redime.","biblical_meaning_en":"One who rescues family from debt, slavery, or loss.","biblical_meaning_es":"El que rescata a la familia de deuda, esclavitud o pérdida.","biblical_meaning_pt":"Aquele que resgata a família de dívida, escravidão ou perda.","historical_background_en":"Legal role in Israelite family law (see Ruth, Leviticus 25).","historical_background_es":"Rol legal en la ley familiar israelita (ver Rut, Levítico 25).","historical_background_pt":"Papel legal na lei familiar israelita (ver Rute, Levítico 25).","practical_application_en":"Rest in Christ your Redeemer — He has bought you back.","practical_application_es":"Descansa en Cristo tu Redentor — Él te ha comprado de nuevo.","practical_application_pt":"Descanse em Cristo seu Redentor — Ele o comprou de volta.","related_words":"padah; lutroō","pronunciation_text":null,"pronunciation_locale":null},
{"id":"af729c80-6045-4cec-b8ad-840172b4068d","slug":"kadosh","order_index":14,"greek":"קָדוֹשׁ","transliteration":"Kadosh","pronunciation":"kah-DOSH","meaning_en":"Holy, set apart.","meaning_es":"Santo, apartado.","meaning_pt":"Santo, separado.","biblical_usage_en":"Repeated three times to express the highest degree.","biblical_usage_es":"Repetido tres veces para expresar el grado más alto.","biblical_usage_pt":"Repetido três vezes para expressar o grau mais elevado.","scripture_refs":"Leviticus 11:44; Isaiah 6:3; 1 Peter 1:16","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"kaˈdoʃ","literal_meaning_en":"Separated, distinct.","literal_meaning_es":"Separado, distinto.","literal_meaning_pt":"Separado, distinto.","biblical_meaning_en":"God's absolute otherness and moral purity.","biblical_meaning_es":"La total alteridad de Dios y su pureza moral.","biblical_meaning_pt":"A total alteridade de Deus e sua pureza moral.","historical_background_en":"Seraphim cry 'kadosh, kadosh, kadosh' in Isaiah 6.","historical_background_es":"Los serafines claman 'kadosh, kadosh, kadosh' en Isaías 6.","historical_background_pt":"Os serafins clamam 'kadosh, kadosh, kadosh' em Isaías 6.","practical_application_en":"Approach God with reverent awe, not casual familiarity.","practical_application_es":"Acércate a Dios con temor reverente, no con familiaridad casual.","practical_application_pt":"Aproxime-se de Deus com temor reverente, não com familiaridade casual.","related_words":"hagios","pronunciation_text":null,"pronunciation_locale":null},
{"id":"0fe8e67d-15e4-477f-b58f-692b222d7a14","slug":"bereshit","order_index":15,"greek":"בְּרֵאשִׁית","transliteration":"Bereshit","pronunciation":"beh-reh-SHEET","meaning_en":"In the beginning.","meaning_es":"En el principio.","meaning_pt":"No princípio.","biblical_usage_en":"Frames all reality under God's authorship.","biblical_usage_es":"Enmarca toda la realidad bajo la autoría de Dios.","biblical_usage_pt":"Enquadra toda a realidade sob a autoria de Deus.","scripture_refs":"Genesis 1:1","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"bereˈʃit","literal_meaning_en":"'At the head of'.","literal_meaning_es":"'A la cabeza de'.","literal_meaning_pt":"'À frente de'.","biblical_meaning_en":"The opening word of the Bible declaring God's original creative act.","biblical_meaning_es":"La palabra inicial de la Biblia que declara el acto creativo original de Dios.","biblical_meaning_pt":"A palavra inicial da Bíblia declarando o ato criativo original de Deus.","historical_background_en":"Hebrew name of the book of Genesis.","historical_background_es":"Nombre hebreo del libro de Génesis.","historical_background_pt":"Nome hebraico do livro de Gênesis.","practical_application_en":"See every beginning — new day, new season — under God's hand.","practical_application_es":"Ve cada comienzo — día nuevo, temporada nueva — bajo la mano de Dios.","practical_application_pt":"Veja cada começo — novo dia, nova temporada — sob a mão de Deus.","related_words":"bara; rosh","pronunciation_text":null,"pronunciation_locale":null},
{"id":"8ad2bb96-99b7-4eef-bb17-ba53897dd1a4","slug":"prince-of-peace","order_index":10,"greek":"Σαρ־Shalom","transliteration":"Sar Shalom","pronunciation":"sar shah-LOME","meaning_en":"Prince of Peace.","meaning_es":"Príncipe de Paz.","meaning_pt":"Príncipe da Paz.","biblical_usage_en":"Fulfilled in Jesus, who reconciles God and humanity.","biblical_usage_es":"Cumplido en Jesús, quien reconcilia a Dios y a la humanidad.","biblical_usage_pt":"Cumprido em Jesus, que reconcilia Deus e a humanidade.","scripture_refs":"Isaiah 9:6-7; Ephesians 2:14-17; Colossians 1:20","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"sar ʃaˈlom","literal_meaning_en":"Ruler of peace / wholeness.","literal_meaning_es":"Gobernante de la paz / plenitud.","literal_meaning_pt":"Governante da paz / plenitude.","biblical_meaning_en":"The Messiah who brings true, lasting shalom.","biblical_meaning_es":"El Mesías que trae verdadera paz duradera.","biblical_meaning_pt":"O Messias que traz paz verdadeira e duradoura.","historical_background_en":"Isaiah 9 predicts a child-king whose government is peace.","historical_background_es":"Isaías 9 predice un niño-rey cuyo gobierno es paz.","historical_background_pt":"Isaías 9 prediz uma criança-rei cujo governo é paz.","practical_application_en":"Receive Christ's peace and become an agent of peace.","practical_application_es":"Recibe la paz de Cristo y sé agente de paz.","practical_application_pt":"Receba a paz de Cristo e seja agente de paz.","related_words":"shalom","pronunciation_text":null,"pronunciation_locale":null},
{"id":"1b6ae6fd-c897-4904-86a9-b0e35df23b28","slug":"shekinah","order_index":16,"greek":"שְׁכִינָה","transliteration":"Shekinah","pronunciation":"sheh-kee-NAH","meaning_en":"The dwelling presence of God.","meaning_es":"La presencia habitante de Dios.","meaning_pt":"A presença habitante de Deus.","biblical_usage_en":"Fulfilled in Jesus ('the Word...tabernacled among us', John 1:14).","biblical_usage_es":"Cumplido en Jesús ('el Verbo...habitó entre nosotros', Juan 1:14).","biblical_usage_pt":"Cumprido em Jesus ('o Verbo...habitou entre nós', João 1:14).","scripture_refs":"Exodus 40:34-38; 1 Kings 8:10-11; John 1:14","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʃexiˈna","literal_meaning_en":"'Dwelling' — from the root 'shakan' (to dwell).","literal_meaning_es":"'Morada' — de la raíz 'shakan' (habitar).","literal_meaning_pt":"'Morada' — da raiz 'shakan' (habitar).","biblical_meaning_en":"The visible manifestation of God's glory among His people.","biblical_meaning_es":"La manifestación visible de la gloria de Dios entre su pueblo.","biblical_meaning_pt":"A manifestação visível da glória de Deus entre seu povo.","historical_background_en":"Rabbinic term describing God's presence in tabernacle and temple.","historical_background_es":"Término rabínico que describe la presencia de Dios en el tabernáculo y el templo.","historical_background_pt":"Termo rabínico descrevendo a presença de Deus no tabernáculo e templo.","practical_application_en":"Welcome God's presence as your daily dwelling place.","practical_application_es":"Da la bienvenida a la presencia de Dios como tu morada diaria.","practical_application_pt":"Acolha a presença de Deus como sua morada diária.","related_words":"kavod","pronunciation_text":null,"pronunciation_locale":null},
{"id":"b1c32a89-034c-407a-ab03-8cf65b6bf150","slug":"amen-heb","order_index":17,"greek":"אָמֵן","transliteration":"Amen","pronunciation":"ah-MEN","meaning_en":"Truly, so be it, firm.","meaning_es":"Ciertamente, así sea, firme.","meaning_pt":"Verdadeiramente, assim seja, firme.","biblical_usage_en":"Jesus is called 'the Amen' — the utterly faithful witness.","biblical_usage_es":"Jesús es llamado 'el Amén' — el testigo totalmente fiel.","biblical_usage_pt":"Jesus é chamado 'o Amém' — a testemunha totalmente fiel.","scripture_refs":"Deuteronomy 27:15-26; Revelation 3:14; 1 Corinthians 14:16","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"ʔaˈmen","literal_meaning_en":"From the root 'aman' — to be firm, faithful.","literal_meaning_es":"De la raíz 'aman' — ser firme, fiel.","literal_meaning_pt":"Da raiz 'aman' — ser firme, fiel.","biblical_meaning_en":"Affirmation and confident agreement, especially in worship.","biblical_meaning_es":"Afirmación y acuerdo confiado, especialmente en la adoración.","biblical_meaning_pt":"Afirmação e concordância confiante, especialmente na adoração.","historical_background_en":"Used in synagogue liturgy long before the church.","historical_background_es":"Usado en la liturgia de la sinagoga mucho antes de la iglesia.","historical_background_pt":"Usado na liturgia da sinagoga muito antes da igreja.","practical_application_en":"Say 'Amen' with heart engaged, not as an empty ending.","practical_application_es":"Di 'Amén' con el corazón, no como final vacío.","practical_application_pt":"Diga 'Amém' com o coração, não como final vazio.","related_words":"emunah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"e62c0c22-7cf0-496c-87fb-6edc6a3ca231","slug":"hallelujah-heb","order_index":18,"greek":"הַלְלוּיָהּ","transliteration":"Hallelu-Yah","pronunciation":"hah-leh-LOO-yah","meaning_en":"Praise Yah (the LORD).","meaning_es":"Alabad a Yah (el SEÑOR).","meaning_pt":"Louvai a Yah (o SENHOR).","biblical_usage_en":"Sung in heaven around the throne (Revelation 19).","biblical_usage_es":"Cantado en el cielo alrededor del trono (Apocalipsis 19).","biblical_usage_pt":"Cantado no céu ao redor do trono (Apocalipse 19).","scripture_refs":"Psalm 150; Revelation 19:1-6","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"haleˈluja","literal_meaning_en":"Compound: 'hallelu' (praise) + 'Yah' (shortened YHWH).","literal_meaning_es":"Compuesto: 'hallelu' (alabad) + 'Yah' (YHWH abreviado).","literal_meaning_pt":"Composto: 'hallelu' (louvai) + 'Yah' (YHWH abreviado).","biblical_meaning_en":"A summons for God's people to praise Him publicly.","biblical_meaning_es":"Un llamado al pueblo de Dios a alabarle públicamente.","biblical_meaning_pt":"Um chamado ao povo de Deus para louvá-Lo publicamente.","historical_background_en":"Frequent in the Psalms of praise (Ps. 146-150).","historical_background_es":"Frecuente en los Salmos de alabanza (Sal. 146-150).","historical_background_pt":"Frequente nos Salmos de louvor (Sl. 146-150).","practical_application_en":"Start your prayer times with praise before requests.","practical_application_es":"Comienza tus tiempos de oración con alabanza antes de pedidos.","practical_application_pt":"Comece seus tempos de oração com louvor antes de pedidos.","related_words":"halal; Yah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"fa3dcd2f-f9b7-4241-bf6b-b08b0469b640","slug":"chai","order_index":19,"greek":"חַי","transliteration":"Chai","pronunciation":"KHY","meaning_en":"Life, alive.","meaning_es":"Vida, vivo.","meaning_pt":"Vida, vivo.","biblical_usage_en":"Used in the greeting 'to life!' (l'chaim).","biblical_usage_es":"Usado en el saludo '¡a la vida!' (l'chaim).","biblical_usage_pt":"Usado na saudação 'à vida!' (l'chaim).","scripture_refs":"Deuteronomy 5:26; Joshua 3:10; Matthew 16:16","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"χaj","literal_meaning_en":"Living, having life.","literal_meaning_es":"Viviente, con vida.","literal_meaning_pt":"Vivente, com vida.","biblical_meaning_en":"God is 'the living God' — active, present, real.","biblical_meaning_es":"Dios es 'el Dios viviente' — activo, presente, real.","biblical_meaning_pt":"Deus é 'o Deus vivo' — ativo, presente, real.","historical_background_en":"Contrasted with lifeless idols throughout the OT.","historical_background_es":"Contrastado con los ídolos sin vida en todo el AT.","historical_background_pt":"Contrastado com ídolos sem vida em todo o AT.","practical_application_en":"Live before the living God today, not a distant idea.","practical_application_es":"Vive ante el Dios viviente hoy, no una idea lejana.","practical_application_pt":"Viva diante do Deus vivo hoje, não uma ideia distante.","related_words":"chayah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"a693ee6b-15fa-49cb-8acd-81a519308a6e","slug":"berit","order_index":20,"greek":"בְּרִית","transliteration":"Berit","pronunciation":"beh-REET","meaning_en":"Covenant.","meaning_es":"Pacto.","meaning_pt":"Aliança.","biblical_usage_en":"Fulfilled and renewed in Christ's blood.","biblical_usage_es":"Cumplido y renovado en la sangre de Cristo.","biblical_usage_pt":"Cumprido e renovado no sangue de Cristo.","scripture_refs":"Genesis 15; Jeremiah 31:31-34; Luke 22:20","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"hebrew","ipa":"bɛˈrit","literal_meaning_en":"A binding agreement, often sealed with a sacrifice.","literal_meaning_es":"Un acuerdo vinculante, a menudo sellado con sacrificio.","literal_meaning_pt":"Um acordo vinculante, muitas vezes selado com sacrifício.","biblical_meaning_en":"God's committed relationship with His people, based on His promise.","biblical_meaning_es":"La relación comprometida de Dios con su pueblo, basada en su promesa.","biblical_meaning_pt":"O relacionamento comprometido de Deus com seu povo, baseado em sua promessa.","historical_background_en":"Framework of the whole Bible: Old and New Covenants.","historical_background_es":"Marco de toda la Biblia: Antiguo y Nuevo Pacto.","historical_background_pt":"Estrutura de toda a Bíblia: Antiga e Nova Aliança.","practical_application_en":"Live as one who belongs to God's covenant family.","practical_application_es":"Vive como uno que pertenece a la familia del pacto de Dios.","practical_application_pt":"Viva como alguém que pertence à família da aliança de Deus.","related_words":"hesed","pronunciation_text":null,"pronunciation_locale":null},
{"id":"209e9ae9-1705-4e1d-8cba-38cfb8b37fdc","slug":"abba-father","order_index":1,"greek":"Ἀββᾶ ὁ πατήρ","transliteration":"Abba ho Patēr","pronunciation":"AH-bah ho pa-TAIR","meaning_en":"Abba, Father — intimate address to God.","meaning_es":"Abba, Padre — dirección íntima a Dios.","meaning_pt":"Abba, Pai — endereço íntimo a Deus.","biblical_usage_en":"Used by Jesus in Gethsemane and by Paul for adopted children.","biblical_usage_es":"Usado por Jesús en Getsemaní y por Pablo para hijos adoptados.","biblical_usage_pt":"Usado por Jesus em Getsêmani e por Paulo para filhos adotados.","scripture_refs":"Mark 14:36; Romans 8:15; Galatians 4:6","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"aˈbːa ho paˈteːr","literal_meaning_en":"Aramaic 'Abba' = father; Greek 'Patēr' = father.","literal_meaning_es":"Arameo 'Abba' = padre; griego 'Patēr' = padre.","literal_meaning_pt":"Aramaico 'Abba' = pai; grego 'Patēr' = pai.","biblical_meaning_en":"The Spirit teaches believers to cry to God with childlike trust.","biblical_meaning_es":"El Espíritu enseña a los creyentes a clamar a Dios con confianza filial.","biblical_meaning_pt":"O Espírito ensina os crentes a clamar a Deus com confiança filial.","historical_background_en":"Jewish children addressed their fathers as 'Abba'.","historical_background_es":"Los niños judíos llamaban a sus padres 'Abba'.","historical_background_pt":"As crianças judias chamavam seus pais de 'Abba'.","practical_application_en":"Approach God as beloved child, not distant petitioner.","practical_application_es":"Acércate a Dios como hijo amado, no como suplicante distante.","practical_application_pt":"Aproxime-se de Deus como filho amado, não suplicante distante.","related_words":"huios; uiothesia","pronunciation_text":null,"pronunciation_locale":null},
{"id":"63221eb6-0d10-4efa-85e1-9a473b8cddf7","slug":"alpha-omega","order_index":2,"greek":"τὸ Α καὶ τὸ Ω","transliteration":"to Alpha kai to Omega","pronunciation":"AL-fah kai oh-MEH-gah","meaning_en":"The Alpha and the Omega.","meaning_es":"El Alfa y la Omega.","meaning_pt":"O Alfa e o Ômega.","biblical_usage_en":"Only used in Revelation, of God and of Christ.","biblical_usage_es":"Solo usado en Apocalipsis, de Dios y de Cristo.","biblical_usage_pt":"Somente usado no Apocalipse, de Deus e de Cristo.","scripture_refs":"Revelation 1:8; 21:6; 22:13","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ˈalfa kai ˈɔːmeɡa","literal_meaning_en":"First and last letters of the Greek alphabet.","literal_meaning_es":"Primera y última letras del alfabeto griego.","literal_meaning_pt":"Primeira e última letras do alfabeto grego.","biblical_meaning_en":"Christ is the beginning and end of all things.","biblical_meaning_es":"Cristo es el principio y el fin de todas las cosas.","biblical_meaning_pt":"Cristo é o princípio e o fim de todas as coisas.","historical_background_en":"Echoes Isaiah's 'I am the first and the last'.","historical_background_es":"Ecoa el 'Yo soy el primero y el último' de Isaías.","historical_background_pt":"Ecoa o 'Eu sou o primeiro e o último' de Isaías.","practical_application_en":"Rest in Christ's sovereignty over your beginning and end.","practical_application_es":"Descansa en la soberanía de Cristo sobre tu principio y fin.","practical_application_pt":"Descanse na soberania de Cristo sobre seu princípio e fim.","related_words":"archē; telos","pronunciation_text":null,"pronunciation_locale":null},
{"id":"8f3d55f2-3b51-40c6-ae98-0cbd1ae205be","slug":"son-of-man","order_index":3,"greek":"ὁ υἱὸς τοῦ ἀνθρώπου","transliteration":"ho Huios tou Anthrōpou","pronunciation":"hwee-OSS too an-THRO-poo","meaning_en":"The Son of Man.","meaning_es":"El Hijo del Hombre.","meaning_pt":"O Filho do Homem.","biblical_usage_en":"Used over 80 times by Jesus in the Gospels.","biblical_usage_es":"Usado más de 80 veces por Jesús en los Evangelios.","biblical_usage_pt":"Usado mais de 80 vezes por Jesus nos Evangelhos.","scripture_refs":"Daniel 7:13-14; Mark 8:31; Matthew 26:64","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ho hyˈjos tu anˈtʰropu","literal_meaning_en":"'The human one' / 'like a son of man'.","literal_meaning_es":"'El humano' / 'como hijo de hombre'.","literal_meaning_pt":"'O humano' / 'como filho do homem'.","biblical_meaning_en":"Jesus' preferred self-title, rooted in Daniel 7's exalted figure.","biblical_meaning_es":"Título propio favorito de Jesús, arraigado en la figura exaltada de Daniel 7.","biblical_meaning_pt":"Título próprio favorito de Jesus, enraizado na figura exaltada de Daniel 7.","historical_background_en":"Daniel 7 pictures 'one like a son of man' given eternal dominion.","historical_background_es":"Daniel 7 muestra 'uno como hijo de hombre' con dominio eterno.","historical_background_pt":"Daniel 7 mostra 'um como filho do homem' com domínio eterno.","practical_application_en":"Trust the humble yet reigning Jesus with your whole life.","practical_application_es":"Confía en Jesús, humilde y reinante, con toda tu vida.","practical_application_pt":"Confie em Jesus, humilde e reinante, com toda a sua vida.","related_words":"Huios tou Theou","pronunciation_text":null,"pronunciation_locale":null},
{"id":"4bd35266-8d3e-4919-9ac6-9cb3be627017","slug":"kingdom-of-god","order_index":4,"greek":"ἡ βασιλεία τοῦ Θεοῦ","transliteration":"hē basileia tou Theou","pronunciation":"bah-see-LAY-ah too theh-OO","meaning_en":"The Kingdom of God.","meaning_es":"El Reino de Dios.","meaning_pt":"O Reino de Deus.","biblical_usage_en":"Jesus' first announcement: 'The kingdom of God is at hand.'","biblical_usage_es":"Primer anuncio de Jesús: 'El reino de Dios se ha acercado.'","biblical_usage_pt":"Primeiro anúncio de Jesus: 'O reino de Deus está próximo.'","scripture_refs":"Mark 1:15; Matthew 6:33; Luke 17:20-21","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"he basiˈlea tu tʰeˈu","literal_meaning_en":"The rule / reign of God.","literal_meaning_es":"El gobierno / reinado de Dios.","literal_meaning_pt":"O governo / reinado de Deus.","biblical_meaning_en":"God's saving reign inaugurated by Jesus and consummated at His return.","biblical_meaning_es":"El reinado salvador de Dios inaugurado por Jesús y consumado en su regreso.","biblical_meaning_pt":"O reinado salvador de Deus inaugurado por Jesus e consumado em sua volta.","historical_background_en":"Central promise of the OT prophets.","historical_background_es":"Promesa central de los profetas del AT.","historical_background_pt":"Promessa central dos profetas do AT.","practical_application_en":"Live as a citizen of God's kingdom, not of anxious kingdoms.","practical_application_es":"Vive como ciudadano del reino de Dios, no de reinos ansiosos.","practical_application_pt":"Viva como cidadão do reino de Deus, não de reinos ansiosos.","related_words":"basileia; basileus","pronunciation_text":null,"pronunciation_locale":null},
{"id":"8f4b351d-18f3-4e86-aa1c-7891d81dc1f0","slug":"lamb-of-god","order_index":5,"greek":"ὁ Ἀμνὸς τοῦ Θεοῦ","transliteration":"ho Amnos tou Theou","pronunciation":"AHM-nos too theh-OO","meaning_en":"The Lamb of God.","meaning_es":"El Cordero de Dios.","meaning_pt":"O Cordeiro de Deus.","biblical_usage_en":"Central image in the Book of Revelation.","biblical_usage_es":"Imagen central en el libro de Apocalipsis.","biblical_usage_pt":"Imagem central no livro do Apocalipse.","scripture_refs":"John 1:29; Isaiah 53:7; Revelation 5:6-14","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ho aˈmnos tu tʰeˈu","literal_meaning_en":"God's own sacrificial lamb.","literal_meaning_es":"El cordero sacrificial de Dios mismo.","literal_meaning_pt":"O cordeiro sacrificial do próprio Deus.","biblical_meaning_en":"Jesus fulfills Passover and the sin-bearing lamb of Isaiah 53.","biblical_meaning_es":"Jesús cumple la Pascua y el cordero portador del pecado de Isaías 53.","biblical_meaning_pt":"Jesus cumpre a Páscoa e o cordeiro portador do pecado de Isaías 53.","historical_background_en":"Announced by John the Baptist at Jesus' baptism.","historical_background_es":"Anunciado por Juan el Bautista en el bautismo de Jesús.","historical_background_pt":"Anunciado por João Batista no batismo de Jesus.","practical_application_en":"Rest in Christ's finished sacrifice for your sin.","practical_application_es":"Descansa en el sacrificio consumado de Cristo por tu pecado.","practical_application_pt":"Descanse no sacrifício consumado de Cristo pelo seu pecado.","related_words":"amnos; pascha","pronunciation_text":null,"pronunciation_locale":null},
{"id":"666a5673-8c5a-4a22-9c40-b9fe6f539c9f","slug":"lion-of-judah","order_index":6,"greek":"ὁ Λέων ὁ ἐκ τῆς φυλῆς Ἰούδα","transliteration":"ho Leōn ek tēs phylēs Iouda","pronunciation":"LEH-own ek tays FOO-lays yoo-DAH","meaning_en":"The Lion of the tribe of Judah.","meaning_es":"El León de la tribu de Judá.","meaning_pt":"O Leão da tribo de Judá.","biblical_usage_en":"Jesus is announced this way in Revelation 5.","biblical_usage_es":"Jesús es anunciado así en Apocalipsis 5.","biblical_usage_pt":"Jesus é anunciado assim em Apocalipse 5.","scripture_refs":"Genesis 49:9-10; Revelation 5:5","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ho ˈleɔːn ek tes fyˈles juˈda","literal_meaning_en":"A royal lion from Judah's tribe.","literal_meaning_es":"Un león real de la tribu de Judá.","literal_meaning_pt":"Um leão real da tribo de Judá.","biblical_meaning_en":"Christ as conquering King fulfilling Jacob's blessing on Judah.","biblical_meaning_es":"Cristo como Rey conquistador cumpliendo la bendición de Jacob a Judá.","biblical_meaning_pt":"Cristo como Rei conquistador cumprindo a bênção de Jacó a Judá.","historical_background_en":"Genesis 49:9-10 promises a ruler from Judah.","historical_background_es":"Génesis 49:9-10 promete un gobernante de Judá.","historical_background_pt":"Gênesis 49:9-10 promete um governante de Judá.","practical_application_en":"Trust the strong Lion who has already conquered.","practical_application_es":"Confía en el fuerte León que ya ha vencido.","practical_application_pt":"Confie no forte Leão que já venceu.","related_words":"Amnos; Basileus","pronunciation_text":null,"pronunciation_locale":null},
{"id":"37b53a53-1013-4c37-9ca7-83e2da5c700f","slug":"bread-of-life","order_index":7,"greek":"ὁ ἄρτος τῆς ζωῆς","transliteration":"ho artos tēs zōēs","pronunciation":"AR-toss tays zoh-AYS","meaning_en":"The Bread of Life.","meaning_es":"El Pan de Vida.","meaning_pt":"O Pão da Vida.","biblical_usage_en":"Central image in John 6.","biblical_usage_es":"Imagen central en Juan 6.","biblical_usage_pt":"Imagem central em João 6.","scripture_refs":"John 6:35, 48-51","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ho ˈartos tes zɔˈɛs","literal_meaning_en":"The life-giving bread.","literal_meaning_es":"El pan que da vida.","literal_meaning_pt":"O pão que dá vida.","biblical_meaning_en":"Jesus as the true sustainer of eternal life.","biblical_meaning_es":"Jesús como verdadero sustentador de la vida eterna.","biblical_meaning_pt":"Jesus como verdadeiro sustentador da vida eterna.","historical_background_en":"Fulfills the manna given in the wilderness.","historical_background_es":"Cumple el maná dado en el desierto.","historical_background_pt":"Cumpre o maná dado no deserto.","practical_application_en":"Feed daily on Christ through Word, prayer, and communion.","practical_application_es":"Aliméntate diariamente de Cristo por la Palabra, la oración y la comunión.","practical_application_pt":"Alimente-se diariamente de Cristo pela Palavra, oração e comunhão.","related_words":"manna; zōē","pronunciation_text":null,"pronunciation_locale":null},
{"id":"fa28bea0-b163-45c1-ab2d-7ca19d6e0fb0","slug":"living-water","order_index":8,"greek":"ὕδωρ ζῶν","transliteration":"hydōr zōn","pronunciation":"HOO-dor ZONE","meaning_en":"Living Water.","meaning_es":"Agua Viva.","meaning_pt":"Água Viva.","biblical_usage_en":"Offered by Jesus to the Samaritan woman.","biblical_usage_es":"Ofrecido por Jesús a la mujer samaritana.","biblical_usage_pt":"Oferecido por Jesus à mulher samaritana.","scripture_refs":"John 4:10-14; John 7:37-39; Jeremiah 2:13","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ˈhydɔːr zɔːn","literal_meaning_en":"Flowing, fresh water — not stagnant.","literal_meaning_es":"Agua corriente, fresca — no estancada.","literal_meaning_pt":"Água corrente, fresca — não estagnada.","biblical_meaning_en":"The Spirit's life given by Christ to satisfy the soul.","biblical_meaning_es":"La vida del Espíritu dada por Cristo para saciar el alma.","biblical_meaning_pt":"A vida do Espírito dada por Cristo para saciar a alma.","historical_background_en":"Rooted in prophetic promises (Jer. 2:13; Ezek. 47).","historical_background_es":"Arraigada en promesas proféticas (Jer. 2:13; Ez. 47).","historical_background_pt":"Enraizada em promessas proféticas (Jr. 2:13; Ez. 47).","practical_application_en":"Bring your inner thirst to Christ — He alone truly satisfies.","practical_application_es":"Lleva tu sed interior a Cristo — solo Él verdaderamente sacia.","practical_application_pt":"Leve sua sede interior a Cristo — só Ele verdadeiramente sacia.","related_words":"pneuma","pronunciation_text":null,"pronunciation_locale":null},
{"id":"fc8e75d5-5e63-49bb-859a-95e4c45b2170","slug":"holy-of-holies","order_index":9,"greek":"τὰ Ἅγια τῶν Ἁγίων","transliteration":"ta Hagia tōn Hagiōn","pronunciation":"HAH-gee-ah tone hah-GEE-own","meaning_en":"The Holy of Holies / Most Holy Place.","meaning_es":"El Lugar Santísimo.","meaning_pt":"O Santo dos Santos.","biblical_usage_en":"Torn curtain at Christ's death opens access for all believers.","biblical_usage_es":"El velo rasgado en la muerte de Cristo abre el acceso a todos los creyentes.","biblical_usage_pt":"O véu rasgado na morte de Cristo abre acesso a todos os crentes.","scripture_refs":"Leviticus 16; Hebrews 9:3; Hebrews 10:19-22","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ta ˈhaɡia ton haˈɡiɔn","literal_meaning_en":"'Holies of holies' — the most holy space.","literal_meaning_es":"'Santo de los santos' — el espacio más santo.","literal_meaning_pt":"'Santo dos santos' — o espaço mais santo.","biblical_meaning_en":"The innermost sanctuary where God's presence dwelt.","biblical_meaning_es":"El santuario más interno donde habitaba la presencia de Dios.","biblical_meaning_pt":"O santuário mais interior onde habitava a presença de Deus.","historical_background_en":"Only the high priest entered, once a year on Yom Kippur.","historical_background_es":"Solo el sumo sacerdote entraba, una vez al año en Yom Kippur.","historical_background_pt":"Somente o sumo sacerdote entrava, uma vez ao ano no Yom Kipur.","practical_application_en":"Draw near to God with confidence through Christ.","practical_application_es":"Acércate a Dios con confianza por medio de Cristo.","practical_application_pt":"Aproxime-se de Deus com confiança por meio de Cristo.","related_words":"kadosh; kavod","pronunciation_text":null,"pronunciation_locale":null},
{"id":"005ef4d8-624e-4096-a3ea-b5f246c073ad","slug":"good-shepherd","order_index":11,"greek":"ὁ ποιμὴν ὁ καλός","transliteration":"ho poimēn ho kalos","pronunciation":"poy-MAIN ho kah-LOSS","meaning_en":"The Good Shepherd.","meaning_es":"El Buen Pastor.","meaning_pt":"O Bom Pastor.","biblical_usage_en":"One of the great 'I am' sayings.","biblical_usage_es":"Uno de los grandes 'Yo soy'.","biblical_usage_pt":"Uma das grandes declarações 'Eu sou'.","scripture_refs":"John 10:11-16; Psalm 23; 1 Peter 2:25","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"ho pojˈmen ho kaˈlos","literal_meaning_en":"'The beautiful/noble shepherd'.","literal_meaning_es":"'El pastor hermoso/noble'.","literal_meaning_pt":"'O pastor belo/nobre'.","biblical_meaning_en":"Jesus, who knows His sheep and gives His life for them.","biblical_meaning_es":"Jesús, que conoce a sus ovejas y da su vida por ellas.","biblical_meaning_pt":"Jesus, que conhece suas ovelhas e dá sua vida por elas.","historical_background_en":"Fulfills God-as-shepherd imagery (Psalm 23; Ezekiel 34).","historical_background_es":"Cumple la imagen de Dios-pastor (Salmo 23; Ezequiel 34).","historical_background_pt":"Cumpre a imagem de Deus-pastor (Salmo 23; Ezequiel 34).","practical_application_en":"Follow the voice of the Good Shepherd above all others.","practical_application_es":"Sigue la voz del Buen Pastor sobre todas las demás.","practical_application_pt":"Siga a voz do Bom Pastor acima de todas as outras.","related_words":"poimēn; ro'eh","pronunciation_text":null,"pronunciation_locale":null},
{"id":"e8e31c9d-93a1-483d-85e3-1ef7db7c2ee6","slug":"hosanna","order_index":12,"greek":"ὡσαννά","transliteration":"hōsanna","pronunciation":"ho-SAH-nah","meaning_en":"Hosanna — 'Save now!'","meaning_es":"Hosanna — '¡Salva ahora!'","meaning_pt":"Hosana — 'Salva agora!'","biblical_usage_en":"Cried by crowds at Jesus' Triumphal Entry.","biblical_usage_es":"Clamado por las multitudes en la Entrada Triunfal de Jesús.","biblical_usage_pt":"Clamado pelas multidões na Entrada Triunfal de Jesus.","scripture_refs":"Psalm 118:25-26; Matthew 21:9,15; Mark 11:9-10","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"hoˈsanːa","literal_meaning_en":"Hebrew 'hoshia na' — save, please.","literal_meaning_es":"Hebreo 'hoshia na' — salva, por favor.","literal_meaning_pt":"Hebraico 'hoshia na' — salva, por favor.","biblical_meaning_en":"A cry for salvation and a shout of joyful praise.","biblical_meaning_es":"Un clamor por salvación y grito de alabanza gozosa.","biblical_meaning_pt":"Um clamor por salvação e grito de louvor jubiloso.","historical_background_en":"From Psalm 118, sung at Passover pilgrimages.","historical_background_es":"Del Salmo 118, cantado en las peregrinaciones de la Pascua.","historical_background_pt":"Do Salmo 118, cantado nas peregrinações da Páscoa.","practical_application_en":"Cry to Jesus for salvation, then celebrate His reign.","practical_application_es":"Clama a Jesús por salvación, luego celebra su reinado.","practical_application_pt":"Clame a Jesus por salvação, depois celebre seu reinado.","related_words":"yasha","pronunciation_text":null,"pronunciation_locale":null},
{"id":"19622605-0011-4b99-879c-da6b0ffbef3d","slug":"maranatha","order_index":13,"greek":"μαρανα θα","transliteration":"Marana tha","pronunciation":"mah-rah-nah THAH","meaning_en":"Maranatha — 'Our Lord, come!'","meaning_es":"Maranata — '¡Señor nuestro, ven!'","meaning_pt":"Maranata — 'Senhor nosso, vem!'","biblical_usage_en":"One of the earliest confessions of Jesus as Lord.","biblical_usage_es":"Una de las confesiones más antiguas de Jesús como Señor.","biblical_usage_pt":"Uma das confissões mais antigas de Jesus como Senhor.","scripture_refs":"1 Corinthians 16:22; Revelation 22:20","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"maraˈna ˈtʰa","literal_meaning_en":"Aramaic prayer / confession retained in Greek text.","literal_meaning_es":"Oración / confesión aramea conservada en el texto griego.","literal_meaning_pt":"Oração / confissão aramaica preservada no texto grego.","biblical_meaning_en":"A longing cry of the early church for Christ's return.","biblical_meaning_es":"Un clamor anhelante de la iglesia primitiva por el regreso de Cristo.","biblical_meaning_pt":"Um clamor anelante da igreja primitiva pela volta de Cristo.","historical_background_en":"Preserved untranslated, showing its liturgical weight.","historical_background_es":"Preservada sin traducir, mostrando su peso litúrgico.","historical_background_pt":"Preservada sem tradução, mostrando seu peso litúrgico.","practical_application_en":"Live with expectant longing — 'Come, Lord Jesus.'","practical_application_es":"Vive con anhelo expectante — 'Ven, Señor Jesús.'","practical_application_pt":"Viva com anseio expectante — 'Vem, Senhor Jesus.'","related_words":"parousia; Kurios","pronunciation_text":null,"pronunciation_locale":null},
{"id":"717ce055-1a6d-4b05-a911-c8ff96d22827","slug":"amen-expr","order_index":14,"greek":"ἀμήν","transliteration":"amēn","pronunciation":"ah-MANE","meaning_en":"Amen — 'so be it, truly'.","meaning_es":"Amén — 'así sea, verdaderamente'.","meaning_pt":"Amém — 'assim seja, verdadeiramente'.","biblical_usage_en":"Jesus uses 'amēn, amēn' to introduce solemn truths.","biblical_usage_es":"Jesús usa 'amén, amén' para introducir verdades solemnes.","biblical_usage_pt":"Jesus usa 'amém, amém' para introduzir verdades solenes.","scripture_refs":"Deuteronomy 27:15-26; John 3:3; 2 Corinthians 1:20","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"aˈmen","literal_meaning_en":"From Hebrew 'aman' — to be firm.","literal_meaning_es":"Del hebreo 'aman' — ser firme.","literal_meaning_pt":"Do hebraico 'aman' — ser firme.","biblical_meaning_en":"Confident affirmation of God's truth and promises.","biblical_meaning_es":"Afirmación confiada de la verdad y promesas de Dios.","biblical_meaning_pt":"Afirmação confiante da verdade e das promessas de Deus.","historical_background_en":"Adopted from synagogue worship into the church.","historical_background_es":"Adoptado de la adoración de la sinagoga a la iglesia.","historical_background_pt":"Adotado da adoração da sinagoga para a igreja.","practical_application_en":"Say 'amen' as a real 'yes' to God, not a habit.","practical_application_es":"Di 'amén' como un verdadero 'sí' a Dios, no un hábito.","practical_application_pt":"Diga 'amém' como um verdadeiro 'sim' a Deus, não um hábito.","related_words":"emunah","pronunciation_text":null,"pronunciation_locale":null},
{"id":"9f1da4c3-120a-49b6-8667-f757690fa75a","slug":"hallelujah-expr","order_index":15,"greek":"ἁλληλουϊά","transliteration":"hallēlouia","pronunciation":"hah-lay-loo-EE-ah","meaning_en":"Hallelujah — 'Praise the LORD'.","meaning_es":"Aleluya — 'Alabad al SEÑOR'.","meaning_pt":"Aleluia — 'Louvai ao SENHOR'.","biblical_usage_en":"Sung in the heavenly worship of Revelation 19.","biblical_usage_es":"Cantado en la adoración celestial de Apocalipsis 19.","biblical_usage_pt":"Cantado na adoração celestial de Apocalipse 19.","scripture_refs":"Psalm 150; Revelation 19:1-6","explanation_en":null,"explanation_es":null,"explanation_pt":null,"created_at":"2026-07-02T19:34:36.215305+00:00","updated_at":"2026-07-02T19:34:36.215305+00:00","language_type":"expression","ipa":"haleluˈja","literal_meaning_en":"Hebrew 'hallelu-Yah' — praise Yah.","literal_meaning_es":"Hebreo 'hallelu-Yah' — alabad a Yah.","literal_meaning_pt":"Hebraico 'hallelu-Yah' — louvai a Yah.","biblical_meaning_en":"A universal, transcultural call to worship the true God.","biblical_meaning_es":"Un llamado universal y transcultural a adorar al Dios verdadero.","biblical_meaning_pt":"Um chamado universal e transcultural a adorar o Deus verdadeiro.","historical_background_en":"Used in the Jewish and Christian worship since antiquity.","historical_background_es":"Usado en la adoración judía y cristiana desde la antigüedad.","historical_background_pt":"Usado na adoração judaica e cristã desde a antiguidade.","practical_application_en":"Begin each day with a real 'Hallelujah' to God.","practical_application_es":"Comienza cada día con un verdadero 'Aleluya' a Dios.","practical_application_pt":"Comece cada dia com um verdadeiro 'Aleluia' a Deus.","related_words":"halal; Yah","pronunciation_text":null,"pronunciation_locale":null}
