FROM jsonb_populate_recordset(NULL::public.library_articles, $pf_library$[
{"id":"8d27c7b7-cae1-424f-9104-7dc312b37a7b","slug":"what-is-the-gospel","category":"doctrine","order_index":1,"is_published":true,"cover_image_url":null,"title_en":"What is the Gospel?","title_es":"¿Qué es el Evangelio?","title_pt":"O que é o Evangelho?","summary_en":"A concise biblical explanation of the good news of Jesus Christ.","summary_es":"Una explicación bíblica concisa de las buenas nuevas de Jesucristo.","summary_pt":"Uma explicação bíblica concisa das boas novas de Jesus Cristo.","body_en":"## The Gospel\n\nThe gospel is the good news that God, through the life, death, and resurrection of Jesus Christ, has provided the way for sinners to be reconciled to Himself.\n\n### Four Truths\n\n1. **God is holy** — Isaiah 6:3\n2. **We are sinners** — Romans 3:23\n3. **Christ died and rose for sinners** — 1 Corinthians 15:3-4\n4. **We respond by faith and repentance** — Acts 20:21\n\nThis is the message the Church proclaims to every generation.","body_es":"## El Evangelio\n\nEl evangelio son las buenas nuevas de que Dios, a través de la vida, muerte y resurrección de Jesucristo, ha provisto el camino para que los pecadores sean reconciliados con Él.\n\n### Cuatro verdades\n\n1. **Dios es santo** — Isaías 6:3\n2. **Somos pecadores** — Romanos 3:23\n3. **Cristo murió y resucitó por los pecadores** — 1 Corintios 15:3-4\n4. **Respondemos por fe y arrepentimiento** — Hechos 20:21","body_pt":"## O Evangelho\n\nO evangelho é a boa nova de que Deus, através da vida, morte e ressurreição de Jesus Cristo, providenciou o caminho para que os pecadores sejam reconciliados com Ele.\n\n### Quatro Verdades\n\n1. **Deus é santo** — Isaías 6:3\n2. **Somos pecadores** — Romanos 3:23\n3. **Cristo morreu e ressuscitou pelos pecadores** — 1 Coríntios 15:3-4\n4. **Respondemos pela fé e arrependimento** — Atos 20:21","created_at":"2026-07-02T18:20:22.717376+00:00","updated_at":"2026-07-02T18:20:22.717376+00:00"},
{"id":"3a938384-c21d-4f5e-9425-64a805ccd94e","slug":"who-is-jesus","category":"christology","order_index":1,"is_published":true,"cover_image_url":null,"title_en":"Who is Jesus Christ?","title_es":"¿Quién es Jesucristo?","title_pt":"Quem é Jesus Cristo?","summary_en":"The eternal Son of God, fully God and fully man.","summary_es":"El eterno Hijo de Dios, plenamente Dios y plenamente hombre.","summary_pt":"O eterno Filho de Deus, plenamente Deus e plenamente homem.","body_en":"## The Person of Christ\n\nJesus of Nazareth is the eternal Son of God who took on human flesh (John 1:14). He is one Person with two natures — fully divine and fully human — united forever without confusion or division.\n\nHe lived a sinless life, died a substitutionary death, rose bodily on the third day, and now reigns at the right hand of the Father.","body_es":"## La Persona de Cristo\n\nJesús de Nazaret es el eterno Hijo de Dios que se hizo carne (Juan 1:14). Es una Persona con dos naturalezas: plenamente divina y plenamente humana.","body_pt":"## A Pessoa de Cristo\n\nJesus de Nazaré é o eterno Filho de Deus que se fez carne (João 1:14). Ele é uma Pessoa com duas naturezas — plenamente divina e plenamente humana.","created_at":"2026-07-02T18:20:22.717376+00:00","updated_at":"2026-07-02T18:20:22.717376+00:00"},
{"id":"74d4548f-4aba-4bc8-88cf-e353d1343912","slug":"inductive-bible-study","category":"hermeneutics","order_index":1,"is_published":true,"cover_image_url":null,"title_en":"Inductive Bible Study Method","title_es":"Método Inductivo de Estudio Bíblico","title_pt":"Método Indutivo de Estudo Bíblico","summary_en":"Observation, interpretation, and application — the three steps for studying any passage.","summary_es":"Observación, interpretación y aplicación: los tres pasos para estudiar cualquier pasaje.","summary_pt":"Observação, interpretação e aplicação — os três passos para estudar qualquer passagem.","body_en":"## Three Steps\n\n1. **Observation** — What does the text say?\n2. **Interpretation** — What does it mean?\n3. **Application** — How do I live it?\n\nAsk the six questions: who, what, when, where, why, how.","body_es":"## Tres Pasos\n\n1. **Observación** — ¿Qué dice el texto?\n2. **Interpretación** — ¿Qué significa?\n3. **Aplicación** — ¿Cómo lo vivo?","body_pt":"## Três Passos\n\n1. **Observação** — O que o texto diz?\n2. **Interpretação** — O que significa?\n3. **Aplicação** — Como vivo isso?","created_at":"2026-07-02T18:20:22.717376+00:00","updated_at":"2026-07-02T18:20:22.717376+00:00"}
]$pf_library$::jsonb)
